window.CODIGO_JAVA = window.CODIGO_JAVA || {};
window.CODIGO_JAVA["usuarios-accesos-ms"] = {"src/main/java/com/mx/josesaid/develop/usuarios_accesos/UsuariosAccesosApplication.java": "package com.mx.josesaid.develop.usuarios_accesos;\n\nimport org.springframework.boot.SpringApplication;\nimport org.springframework.boot.autoconfigure.SpringBootApplication;\nimport org.springframework.boot.context.properties.ConfigurationPropertiesScan;\nimport org.springframework.scheduling.annotation.EnableScheduling;\n\n/** Punto de entrada de usuarios-accesos-ms. */\n@SpringBootApplication\n@EnableScheduling\n@ConfigurationPropertiesScan\npublic class UsuariosAccesosApplication {\n\n    /** Arranca la aplicación Spring Boot. */\n    public static void main(String[] args) {\n        SpringApplication.run(UsuariosAccesosApplication.class, args);\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/usuarios_accesos/api/AuthController.java": "package com.mx.josesaid.develop.usuarios_accesos.api;\n\nimport com.mx.josesaid.develop.usuarios_accesos.application.SesionService;\nimport com.mx.josesaid.develop.usuarios_accesos.application.UsuarioService;\nimport com.mx.josesaid.develop.usuarios_accesos.config.PropiedadesJwt;\nimport com.mx.josesaid.develop.usuarios_accesos.domain.Usuario;\nimport com.mx.josesaid.develop.usuarios_accesos.infrastructure.security.EmisorTokens;\nimport jakarta.validation.Valid;\nimport jakarta.validation.constraints.Email;\nimport jakarta.validation.constraints.NotBlank;\nimport jakarta.validation.constraints.Size;\nimport java.util.UUID;\nimport org.springframework.http.HttpStatus;\nimport org.springframework.security.core.annotation.AuthenticationPrincipal;\nimport org.springframework.security.oauth2.jwt.Jwt;\nimport org.springframework.web.bind.annotation.PostMapping;\nimport org.springframework.web.bind.annotation.ResponseStatus;\nimport org.springframework.web.bind.annotation.RequestBody;\nimport org.springframework.web.bind.annotation.RequestMapping;\nimport org.springframework.web.bind.annotation.RestController;\n\n/** Inicio de sesión. Público: es la única forma de obtener un token. */\n@RestController\n@RequestMapping(\"/v1/auth\")\npublic class AuthController {\n\n    private final UsuarioService servicio;\n    private final EmisorTokens emisor;\n    private final PropiedadesJwt propiedades;\n    private final SesionService sesiones;\n\n    /** Recibe el servicio de usuarios, el emisor de tokens, las propiedades JWT y el servicio de sesiones. */\n    public AuthController(UsuarioService servicio, EmisorTokens emisor, PropiedadesJwt propiedades,\n                          SesionService sesiones) {\n        this.servicio = servicio;\n        this.emisor = emisor;\n        this.propiedades = propiedades;\n        this.sesiones = sesiones;\n    }\n\n    /** Inicia sesión con correo y contraseña. Devuelve un access token y un refresh token. */\n    @PostMapping(\"/login\")\n    public TokenRespuesta login(@Valid @RequestBody LoginSolicitud solicitud) {\n        Usuario usuario = servicio.autenticar(solicitud.correo(), solicitud.password());\n        return respuesta(sesiones.iniciar(usuario));\n    }\n\n    /** Rota el refresh token y devuelve un access token y un refresh token nuevos. */\n    @PostMapping(\"/refresh\")\n    public TokenRespuesta refrescar(@Valid @RequestBody RefrescoSolicitud solicitud) {\n        return respuesta(sesiones.refrescar(solicitud.refreshToken()));\n    }\n\n    /** Sustituye la contraseña temporal. Público: el usuario aún no tiene token. */\n    @PostMapping(\"/cambiar-password-inicial\")\n    @ResponseStatus(HttpStatus.NO_CONTENT)\n    public void cambiarPasswordInicial(@Valid @RequestBody CambioPasswordSolicitud solicitud) {\n        servicio.cambiarPasswordTemporal(solicitud.correo(), solicitud.passwordActual(), solicitud.passwordNueva());\n    }\n\n    /** Cierra la sesión del refresh token dado. Público: basta con tener el token. */\n    @PostMapping(\"/logout\")\n    @ResponseStatus(HttpStatus.NO_CONTENT)\n    public void cerrar(@Valid @RequestBody RefrescoSolicitud solicitud) {\n        sesiones.cerrar(solicitud.refreshToken());\n    }\n\n    /** Cierra todas las sesiones del usuario autenticado. */\n    @PostMapping(\"/logout-todas\")\n    @ResponseStatus(HttpStatus.NO_CONTENT)\n    public void cerrarTodas(@AuthenticationPrincipal Jwt jwt) {\n        sesiones.cerrarTodas(UUID.fromString(jwt.getSubject()));\n    }\n\n    /** Arma la respuesta con los dos tokens, el tipo Bearer y la vigencia del access token en segundos. */\n    private TokenRespuesta respuesta(SesionService.Par par) {\n        return new TokenRespuesta(par.accessToken(), \"Bearer\", propiedades.duracion().toSeconds(), par.refreshToken());\n    }\n\n    /**\n     * Datos de inicio de sesión: correo y contraseña.\n     *\n     * @param correo correo electrónico de contacto, de tipo {@code String}.\n     * @param password password, de tipo {@code String}.\n     */\n    public record LoginSolicitud(@NotBlank @Email String correo, @NotBlank String password) {\n    }\n\n    /**\n     * Refresh token a rotar o a cerrar.\n     *\n     * @param refreshToken refresh token, de tipo {@code String}.\n     */\n    public record RefrescoSolicitud(@NotBlank String refreshToken) {\n    }\n\n    /**\n     * Datos para cambiar la contraseña temporal. La nueva debe tener entre 12 y 100 caracteres.\n     *\n     * @param correo correo electrónico de contacto, de tipo {@code String}.\n     * @param passwordActual password actual, de tipo {@code String}.\n     * @param passwordNueva password nueva, de tipo {@code String}.\n     */\n    public record CambioPasswordSolicitud(\n            @NotBlank @Email String correo,\n            @NotBlank String passwordActual,\n            @NotBlank @Size(min = 12, max = 100) String passwordNueva) {\n    }\n\n    /**\n     * Respuesta con los tokens. expiresIn va en segundos.\n     *\n     * @param accessToken access token, de tipo {@code String}.\n     * @param tokenType token type, de tipo {@code String}.\n     * @param expiresIn expires in, de tipo {@code long}.\n     * @param refreshToken refresh token, de tipo {@code String}.\n     */\n    public record TokenRespuesta(String accessToken, String tokenType, long expiresIn, String refreshToken) {\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/usuarios_accesos/api/Enmascarado.java": "package com.mx.josesaid.develop.usuarios_accesos.api;\n\n/** Oculta datos personales en las respuestas de la API. Nunca se usa en logs: los logs no registran estos datos. */\npublic final class Enmascarado {\n\n    /** Clase de utilidad para enmascarar datos personales; no se instancia. */\n    private Enmascarado() {\n    }\n\n    /** {@code juan.perez@mail.com} se muestra como {@code ju***@mail.com}. */\n    public static String correo(String correo) {\n        if (correo == null) {\n            return null;\n        }\n        int arroba = correo.indexOf('@');\n        if (arroba <= 0) {\n            return \"***\";\n        }\n        return correo.substring(0, Math.min(2, arroba)) + \"***\" + correo.substring(arroba);\n    }\n\n    /** {@code Juan Pérez} se muestra como {@code J***}. */\n    public static String nombre(String nombre) {\n        if (nombre == null || nombre.isBlank()) {\n            return null;\n        }\n        return nombre.charAt(0) + \"***\";\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/usuarios_accesos/api/JwksController.java": "package com.mx.josesaid.develop.usuarios_accesos.api;\n\nimport com.nimbusds.jose.jwk.JWKSet;\nimport java.util.Map;\nimport org.springframework.web.bind.annotation.GetMapping;\nimport org.springframework.web.bind.annotation.RestController;\n\n/** Publica las claves públicas con las que los demás servicios y el gateway validan los tokens. */\n@RestController\npublic class JwksController {\n\n    private final Map<String, Object> jwks;\n\n    /** Recibe el conjunto de claves públicas con el que se validan los tokens. */\n    public JwksController(JWKSet clavesPublicas) {\n        this.jwks = clavesPublicas.toJSONObject();\n    }\n\n    /** Publica las claves públicas en formato JWKS. Los demás servicios las usan para validar tokens sin consultar a este servicio. */\n    @GetMapping(value = \"/.well-known/jwks.json\", produces = \"application/json\")\n    public Map<String, Object> jwks() {\n        return jwks;\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/usuarios_accesos/api/ManejadorErrores.java": "package com.mx.josesaid.develop.usuarios_accesos.api;\n\nimport com.mx.josesaid.develop.usuarios_accesos.domain.BloqueoException;\nimport com.mx.josesaid.develop.usuarios_accesos.domain.CambioPasswordRequeridoException;\nimport com.mx.josesaid.develop.usuarios_accesos.domain.ConflictoException;\nimport com.mx.josesaid.develop.usuarios_accesos.domain.CredencialesInvalidasException;\nimport com.mx.josesaid.develop.usuarios_accesos.domain.RecursoNoEncontradoException;\nimport com.mx.josesaid.develop.usuarios_accesos.domain.ReglaDeNegocioException;\nimport java.net.URI;\nimport java.util.stream.Collectors;\nimport org.springframework.http.HttpStatus;\nimport org.springframework.http.ProblemDetail;\nimport org.springframework.web.bind.MethodArgumentNotValidException;\nimport org.springframework.web.bind.annotation.ExceptionHandler;\nimport org.springframework.web.bind.annotation.RestControllerAdvice;\n\n/**\n * Traduce excepciones a respuestas RFC 9457 (ProblemDetail).\n *\n * <p>Cada error tiene un {@code type} estable con el prefijo {@code urn:josesaid:usuarios-accesos:error:}.\n */\n@RestControllerAdvice\npublic class ManejadorErrores {\n\n    private static final String PREFIJO = \"urn:josesaid:usuarios-accesos:error:\";\n\n    /** Convierte credenciales incorrectas en un problema HTTP. */\n    @ExceptionHandler(CredencialesInvalidasException.class)\n    ProblemDetail credenciales(CredencialesInvalidasException ex) {\n        return problema(HttpStatus.UNAUTHORIZED, \"credenciales-invalidas\", ex.getMessage());\n    }\n\n    /** Convierte una contraseña temporal pendiente de cambio en un problema HTTP. */\n    @ExceptionHandler(CambioPasswordRequeridoException.class)\n    ProblemDetail cambioRequerido(CambioPasswordRequeridoException ex) {\n        return problema(HttpStatus.FORBIDDEN, \"cambio-password-requerido\", ex.getMessage());\n    }\n\n    /** Convierte una cuenta bloqueada por intentos fallidos en un problema HTTP. */\n    @ExceptionHandler(BloqueoException.class)\n    ProblemDetail bloqueo(BloqueoException ex) {\n        return problema(HttpStatus.LOCKED, \"cuenta-bloqueada\", ex.getMessage());\n    }\n\n    /** Convierte un recurso inexistente en un problema HTTP. */\n    @ExceptionHandler(RecursoNoEncontradoException.class)\n    ProblemDetail noEncontrado(RecursoNoEncontradoException ex) {\n        return problema(HttpStatus.NOT_FOUND, \"no-encontrado\", ex.getMessage());\n    }\n\n    /** Convierte un conflicto de estado en un problema HTTP. */\n    @ExceptionHandler(ConflictoException.class)\n    ProblemDetail conflicto(ConflictoException ex) {\n        return problema(HttpStatus.CONFLICT, \"conflicto\", ex.getMessage());\n    }\n\n    /** Convierte una regla de negocio incumplida en un problema HTTP. */\n    @ExceptionHandler(ReglaDeNegocioException.class)\n    ProblemDetail reglaDeNegocio(ReglaDeNegocioException ex) {\n        return problema(HttpStatus.UNPROCESSABLE_ENTITY, \"regla-de-negocio\", ex.getMessage());\n    }\n\n    /** Convierte errores de validación en un problema HTTP con el detalle de cada campo. */\n    @ExceptionHandler(MethodArgumentNotValidException.class)\n    ProblemDetail validacion(MethodArgumentNotValidException ex) {\n        String detalle = ex.getBindingResult().getFieldErrors().stream()\n                .map(e -> e.getField() + \": \" + e.getDefaultMessage())\n                .collect(Collectors.joining(\"; \"));\n        return problema(HttpStatus.BAD_REQUEST, \"datos-invalidos\", detalle);\n    }\n\n    /** Construye la respuesta de error con su estatus, código y detalle. */\n    private static ProblemDetail problema(HttpStatus estatus, String slug, String detalle) {\n        ProblemDetail pd = ProblemDetail.forStatusAndDetail(estatus, detalle);\n        pd.setType(URI.create(PREFIJO + slug));\n        pd.setTitle(estatus.getReasonPhrase());\n        return pd;\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/usuarios_accesos/api/UsuarioController.java": "package com.mx.josesaid.develop.usuarios_accesos.api;\n\nimport com.mx.josesaid.develop.usuarios_accesos.application.UsuarioService;\nimport com.mx.josesaid.develop.usuarios_accesos.domain.Rol;\nimport com.mx.josesaid.develop.usuarios_accesos.domain.Usuario;\nimport jakarta.validation.Valid;\nimport jakarta.validation.constraints.Email;\nimport jakarta.validation.constraints.NotBlank;\nimport jakarta.validation.constraints.NotEmpty;\nimport jakarta.validation.constraints.NotNull;\nimport jakarta.validation.constraints.Size;\nimport java.util.List;\nimport java.util.Set;\nimport java.util.UUID;\nimport org.springframework.http.HttpStatus;\nimport org.springframework.security.access.prepost.PreAuthorize;\nimport org.springframework.web.bind.annotation.GetMapping;\nimport org.springframework.web.bind.annotation.PathVariable;\nimport org.springframework.web.bind.annotation.PostMapping;\nimport org.springframework.web.bind.annotation.PutMapping;\nimport org.springframework.web.bind.annotation.RequestBody;\nimport org.springframework.web.bind.annotation.RequestMapping;\nimport org.springframework.web.bind.annotation.ResponseStatus;\nimport org.springframework.web.bind.annotation.RestController;\n\n/** Administración de usuarios. Solo el rol ADMIN puede usar estos endpoints. */\n@RestController\n@RequestMapping(\"/v1/usuarios\")\n@PreAuthorize(\"hasRole('ADMIN')\")\npublic class UsuarioController {\n\n    private final UsuarioService servicio;\n\n    /** Recibe el servicio de usuarios. */\n    public UsuarioController(UsuarioService servicio) {\n        this.servicio = servicio;\n    }\n\n    /** Da de alta un usuario con su contraseña temporal. Debe cambiarla antes de su primer inicio de sesión. */\n    @PostMapping\n    @ResponseStatus(HttpStatus.CREATED)\n    public UsuarioRespuesta crear(@Valid @RequestBody CrearUsuarioSolicitud solicitud) {\n        Usuario usuario = servicio.crearConPasswordTemporal(solicitud.correo(), solicitud.nombreCompleto(),\n                solicitud.password(), solicitud.roles());\n        return UsuarioRespuesta.de(usuario);\n    }\n\n    /** Lista los usuarios más recientes. */\n    @GetMapping\n    public List<UsuarioRespuesta> listar() {\n        return servicio.listarRecientes().stream().map(UsuarioRespuesta::de).toList();\n    }\n\n    /** Devuelve un usuario por id. */\n    @GetMapping(\"/{id}\")\n    public UsuarioRespuesta obtener(@PathVariable UUID id) {\n        return UsuarioRespuesta.de(servicio.obtener(id));\n    }\n\n    /** Reemplaza los roles de un usuario. Exige un motivo para la auditoría. */\n    @PutMapping(\"/{id}/roles\")\n    public UsuarioRespuesta asignarRoles(@PathVariable UUID id,\n                                         @Valid @RequestBody AsignarRolesSolicitud solicitud) {\n        return UsuarioRespuesta.de(servicio.asignarRoles(id, solicitud.roles(), solicitud.motivo()));\n    }\n\n    /** Asigna el área de un usuario. Exige un motivo para la auditoría. */\n    @PutMapping(\"/{id}/area\")\n    public UsuarioRespuesta asignarArea(@PathVariable UUID id,\n                                        @Valid @RequestBody AsignarAreaSolicitud solicitud) {\n        return UsuarioRespuesta.de(servicio.asignarArea(id, solicitud.area(), solicitud.motivo()));\n    }\n\n    /** Da de baja al usuario de forma definitiva. */\n    @PostMapping(\"/{id}/baja\")\n    public UsuarioRespuesta darDeBaja(@PathVariable UUID id) {\n        return UsuarioRespuesta.de(servicio.darDeBaja(id));\n    }\n\n    /**\n     * Datos para crear un usuario: correo, nombre completo, contraseña temporal y roles.\n     *\n     * @param correo correo electrónico de contacto, de tipo {@code String}.\n     * @param nombreCompleto nombre completo, de tipo {@code String}.\n     * @param password password, de tipo {@code String}.\n     * @param roles roles asignados, de tipo {@code Set<Rol>}.\n     */\n    public record CrearUsuarioSolicitud(\n            @NotBlank @Email String correo,\n            @NotBlank String nombreCompleto,\n            @NotBlank String password,\n            @NotEmpty Set<Rol> roles) {\n    }\n\n    /**\n     * Área a asignar y motivo del cambio.\n     *\n     * @param area área de negocio a la que pertenece, de tipo {@code String}.\n     * @param motivo motivo del registro o de la acción, de tipo {@code String}.\n     */\n    public record AsignarAreaSolicitud(\n            @NotBlank @Size(max = 40) String area,\n            @NotBlank String motivo) {\n    }\n\n    /**\n     * Roles nuevos y motivo del cambio.\n     *\n     * @param roles roles asignados, de tipo {@code Set<Rol>}.\n     * @param motivo motivo del registro o de la acción, de tipo {@code String}.\n     */\n    public record AsignarRolesSolicitud(\n            @NotNull @NotEmpty Set<Rol> roles,\n            @NotBlank String motivo) {\n    }\n\n    /**\n     * Respuesta con datos personales enmascarados.\n     *\n     * @param id identificador único del registro, de tipo {@code UUID}.\n     * @param correo correo electrónico de contacto, de tipo {@code String}.\n     * @param nombreCompleto nombre completo, de tipo {@code String}.\n     * @param estatus estado actual del registro, de tipo {@code String}.\n     * @param roles roles asignados, de tipo {@code Set<Rol>}.\n     * @param area área de negocio a la que pertenece, de tipo {@code String}.\n     */\n    public record UsuarioRespuesta(UUID id, String correo, String nombreCompleto, String estatus, Set<Rol> roles,\n                                   String area) {\n        /** Convierte un usuario en su respuesta. */\n        static UsuarioRespuesta de(Usuario u) {\n            return new UsuarioRespuesta(u.getId(), Enmascarado.correo(u.getCorreo()),\n                    Enmascarado.nombre(u.getNombreCompleto()), u.getEstatus().name(), u.getRoles(),\n                    u.getArea());\n        }\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/usuarios_accesos/application/EventoDominio.java": "package com.mx.josesaid.develop.usuarios_accesos.application;\n\nimport java.util.Map;\n\n/**\n * Evento de negocio emitido por la capa de aplicación.\n *\n * @param tipo       nombre del evento, por ejemplo {@code usuario-bloqueado}\n * @param agregadoId identificador del agregado, usado como clave de partición\n * @param datos      contenido del evento; no incluye datos personales en claro\n */\npublic record EventoDominio(String tipo, String agregadoId, Map<String, Object> datos) {\n}\n", "src/main/java/com/mx/josesaid/develop/usuarios_accesos/application/PublicadorEventos.java": "package com.mx.josesaid.develop.usuarios_accesos.application;\n\n/** Puerto de publicación de eventos. La implementación usa el patrón outbox. */\npublic interface PublicadorEventos {\n\n    void publicar(EventoDominio evento);\n}\n", "src/main/java/com/mx/josesaid/develop/usuarios_accesos/application/SesionService.java": "package com.mx.josesaid.develop.usuarios_accesos.application;\n\nimport java.util.Map;\n\nimport com.mx.josesaid.develop.usuarios_accesos.domain.BloqueoException;\nimport com.mx.josesaid.develop.usuarios_accesos.domain.CredencialesInvalidasException;\nimport com.mx.josesaid.develop.usuarios_accesos.domain.RefreshToken;\nimport com.mx.josesaid.develop.usuarios_accesos.domain.RefreshTokenRepositorio;\nimport com.mx.josesaid.develop.usuarios_accesos.domain.Usuario;\nimport com.mx.josesaid.develop.usuarios_accesos.domain.UsuarioRepositorio;\nimport com.mx.josesaid.develop.usuarios_accesos.infrastructure.security.EmisorTokens;\nimport java.security.MessageDigest;\nimport java.security.NoSuchAlgorithmException;\nimport java.security.SecureRandom;\nimport java.time.Clock;\nimport java.time.Duration;\nimport java.time.Instant;\nimport java.util.Base64;\nimport java.util.HexFormat;\nimport java.util.UUID;\nimport org.springframework.stereotype.Service;\nimport org.springframework.transaction.annotation.Transactional;\n\n/**\n * Sesiones: emite access token y refresh token, rota el refresh en cada uso y revoca la sesión\n * si se reutiliza un token ya rotado (posible robo).\n */\n@Service\npublic class SesionService {\n\n    /** Vigencia del refresh token desde su último uso. */\n    public static final Duration DURACION_REFRESCO = Duration.ofDays(7);\n\n    public static final String EVENTO_SESION_CERRADA = \"sesion-cerrada\";\n    public static final String EVENTO_SESIONES_USUARIO_CERRADAS = \"sesiones-usuario-cerradas\";\n\n    private static final SecureRandom ALEATORIO = new SecureRandom();\n\n    /**\n     * Access token y refresh token en texto plano. Solo se devuelven al cliente, nunca se guardan.\n     *\n     * @param accessToken access token, de tipo {@code String}.\n     * @param refreshToken refresh token, de tipo {@code String}.\n     */\n    public record Par(String accessToken, String refreshToken) {\n    }\n\n    private final RefreshTokenRepositorio refrescos;\n    private final UsuarioRepositorio usuarios;\n    private final EmisorTokens emisor;\n    private final Clock reloj;\n    private final PublicadorEventos publicador;\n\n    /** Recibe los repositorios de refresh tokens y usuarios, el emisor de tokens, el reloj y el publicador de eventos. */\n    public SesionService(RefreshTokenRepositorio refrescos, UsuarioRepositorio usuarios,\n                         EmisorTokens emisor, Clock reloj,\n                         PublicadorEventos publicador) {\n        this.refrescos = refrescos;\n        this.usuarios = usuarios;\n        this.emisor = emisor;\n        this.reloj = reloj;\n        this.publicador = publicador;\n    }\n\n    /** Inicia una sesión nueva tras un login exitoso. */\n    @Transactional\n    public Par iniciar(Usuario usuario) {\n        return emitirPar(usuario, UUID.randomUUID(), Instant.now(reloj));\n    }\n\n    /**\n     * Rota el refresh token. Si el token ya fue usado, revoca toda su familia; esa revocación\n     * se conserva aunque la excepción haga rollback, por eso noRollbackFor.\n     */\n    @Transactional(noRollbackFor = {CredencialesInvalidasException.class, BloqueoException.class})\n    public Par refrescar(String refrescoPlano) {\n        Instant ahora = Instant.now(reloj);\n        RefreshToken actual = refrescos.buscarPorHash(hash(refrescoPlano))\n                .orElseThrow(SesionService::invalido);\n        if (actual.usadoUtc() != null) {\n            refrescos.revocarFamilia(actual.familiaId(), ahora);\n            throw invalido();\n        }\n        if (!actual.activo(ahora)) {\n            throw invalido();\n        }\n        Usuario usuario = usuarios.buscarPorId(actual.usuarioId()).orElseThrow(SesionService::invalido);\n        usuario.verificarAcceso(ahora);\n        usuarios.guardar(usuario);\n        refrescos.guardar(actual.comoUsado(ahora));\n        return emitirPar(usuario, actual.familiaId(), ahora);\n    }\n\n    /** Cierra la sesión del refresh token dado. Si el token no existe, no hace nada. */\n    @Transactional\n    public void cerrar(String refrescoPlano) {\n        refrescos.buscarPorHash(hash(refrescoPlano))\n                .ifPresent(t -> {\n                    Instant ahora = Instant.now(reloj);\n                    refrescos.revocarFamilia(t.familiaId(), ahora);\n                    publicador.publicar(new EventoDominio(EVENTO_SESION_CERRADA, t.usuarioId().toString(),\n                            Map.of(\"sid\", t.familiaId().toString(), \"usuarioId\", t.usuarioId().toString(),\n                                   \"ocurridoEn\", ahora.toString())));\n                });\n    }\n\n    /** Cierra todas las sesiones del usuario. */\n    @Transactional\n    public void cerrarTodas(UUID usuarioId) {\n        Instant ahora = Instant.now(reloj);\n        refrescos.revocarTodasDeUsuario(usuarioId, ahora);\n        publicador.publicar(new EventoDominio(EVENTO_SESIONES_USUARIO_CERRADAS, usuarioId.toString(),\n                Map.of(\"usuarioId\", usuarioId.toString(), \"ocurridoEn\", ahora.toString())));\n    }\n\n    /** Crea un access token y un refresh token nuevos, y guarda solo el hash del refresh token. Los tokens de una misma sesión comparten familia. */\n    private Par emitirPar(Usuario usuario, UUID familia, Instant ahora) {\n        String refresco = nuevoRefresco();\n        refrescos.guardar(new RefreshToken(UUID.randomUUID(), usuario.getId(), familia, hash(refresco),\n                ahora.plus(DURACION_REFRESCO), null, null));\n        return new Par(emisor.emitir(usuario, familia), refresco);\n    }\n\n    /** Genera un refresh token aleatorio de 256 bits, en Base64 sin relleno. */\n    private static String nuevoRefresco() {\n        byte[] bytes = new byte[32];\n        ALEATORIO.nextBytes(bytes);\n        return Base64.getUrlEncoder().withoutPadding().encodeToString(bytes);\n    }\n\n    /** Calcula el SHA-256 de un token en hexadecimal. Solo el hash se guarda, nunca el token. */\n    static String hash(String valor) {\n        try {\n            byte[] digest = MessageDigest.getInstance(\"SHA-256\")\n                    .digest(valor.getBytes(java.nio.charset.StandardCharsets.UTF_8));\n            return HexFormat.of().formatHex(digest);\n        } catch (NoSuchAlgorithmException e) {\n            throw new IllegalStateException(\"SHA-256 no disponible\", e);\n        }\n    }\n\n    /** Devuelve la excepción genérica de token inválido, sin revelar la causa exacta. */\n    private static CredencialesInvalidasException invalido() {\n        return new CredencialesInvalidasException();\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/usuarios_accesos/application/UsuarioService.java": "package com.mx.josesaid.develop.usuarios_accesos.application;\n\nimport io.micrometer.core.instrument.MeterRegistry;\n\nimport com.mx.josesaid.develop.usuarios_accesos.domain.CambioPasswordRequeridoException;\nimport com.mx.josesaid.develop.usuarios_accesos.domain.ReglaDeNegocioException;\nimport com.mx.josesaid.develop.usuarios_accesos.domain.CredencialesInvalidasException;\nimport com.mx.josesaid.develop.usuarios_accesos.domain.ConflictoException;\nimport com.mx.josesaid.develop.usuarios_accesos.domain.RecursoNoEncontradoException;\nimport com.mx.josesaid.develop.usuarios_accesos.domain.Rol;\nimport com.mx.josesaid.develop.usuarios_accesos.domain.Usuario;\nimport com.mx.josesaid.develop.usuarios_accesos.domain.UsuarioRepositorio;\nimport java.time.Clock;\nimport java.time.Instant;\nimport java.util.Collection;\nimport java.util.List;\nimport java.util.Map;\nimport java.util.Set;\nimport java.util.UUID;\nimport java.util.stream.Collectors;\nimport org.springframework.security.crypto.password.PasswordEncoder;\nimport org.springframework.stereotype.Service;\nimport org.springframework.transaction.annotation.Transactional;\n\n/**\n * Casos de uso de identidad: alta, autenticación, asignación de roles y baja.\n *\n * <p>Las transacciones son de la capa de aplicación. El intento fallido se guarda aunque\n * la respuesta sea 401, por eso {@code autenticar} no revierte ante credenciales incorrectas.\n */\n@Service\npublic class UsuarioService {\n\n    public static final String EVENTO_USUARIO_BLOQUEADO = \"usuario-bloqueado\";\n    public static final String EVENTO_ROL_ASIGNADO = \"rol-asignado\";\n    public static final String EVENTO_AREA_ASIGNADA = \"area-asignada\";\n\n    private final UsuarioRepositorio repositorio;\n    private final PasswordEncoder passwordEncoder;\n    private final PublicadorEventos publicador;\n    private final Clock reloj;\n    private final MeterRegistry metricas;\n\n    /** Recibe las dependencias de usuarios: repositorio, codificador de contraseñas y demás colaboradores. */\n    public UsuarioService(UsuarioRepositorio repositorio, PasswordEncoder passwordEncoder,\n                          PublicadorEventos publicador, Clock reloj, MeterRegistry metricas) {\n        this.repositorio = repositorio;\n        this.passwordEncoder = passwordEncoder;\n        this.publicador = publicador;\n        this.reloj = reloj;\n        this.metricas = metricas;\n    }\n\n    /** Cuenta una operación en las métricas de usuarios, por nombre. */\n    private void contar(String nombre) {\n        metricas.counter(nombre).increment();\n    }\n\n    /** Crea un usuario activo con contraseña temporal. Valida el correo, que no esté registrado y que los roles sean válidos. */\n    @Transactional\n    public Usuario crear(String correo, String nombreCompleto, String passwordPlano, Set<Rol> roles) {\n        String correoNormalizado = Usuario.normalizarCorreo(correo);\n        if (repositorio.existePorCorreo(correoNormalizado)) {\n            throw new ConflictoException(\"Ya existe un usuario con ese correo\");\n        }\n        if (roles != null && roles.contains(Rol.JEFE_AREA)) {\n            throw new ReglaDeNegocioException(\"Cree el usuario, asígnele un área y después el rol JEFE_AREA\");\n        }\n        String hash = passwordEncoder.encode(passwordPlano == null ? \"\" : passwordPlano);\n        Usuario nuevo = repositorio.guardar(Usuario.crear(correoNormalizado, nombreCompleto, hash, roles));\n        contar(\"usuarios.altas\");\n        return nuevo;\n    }\n\n    /** Da de alta una cuenta con contraseña temporal: debe cambiarla antes de iniciar sesión. */\n    @Transactional\n    public Usuario crearConPasswordTemporal(String correo, String nombreCompleto, String passwordPlano, Set<Rol> roles) {\n        Usuario creado = crear(correo, nombreCompleto, passwordPlano, roles);\n        creado.marcarPasswordTemporal();\n        return repositorio.guardar(creado);\n    }\n\n    /**\n     * Valida credenciales. Devuelve el usuario si son correctas.\n     *\n     * <p>{@code noRollbackFor} conserva el contador de intentos fallidos cuando las credenciales son incorrectas.\n     */\n    @Transactional(noRollbackFor = CredencialesInvalidasException.class)\n    public Usuario autenticar(String correo, String passwordPlano) {\n        Instant ahora = Instant.now(reloj);\n        Usuario usuario = repositorio.buscarPorCorreo(Usuario.normalizarCorreo(correo))\n                .orElseThrow(CredencialesInvalidasException::new);\n\n        usuario.verificarAcceso(ahora);\n\n        if (!passwordEncoder.matches(passwordPlano == null ? \"\" : passwordPlano, usuario.getPasswordHash())) {\n            boolean bloqueadoAhora = usuario.registrarIntentoFallido(ahora);\n            repositorio.guardar(usuario);\n            contar(\"usuarios.login.fallidos\");\n            if (bloqueadoAhora) {\n                contar(\"usuarios.bloqueos\");\n                publicador.publicar(new EventoDominio(\n                        EVENTO_USUARIO_BLOQUEADO,\n                        usuario.getId().toString(),\n                        Map.of(\"usuarioId\", usuario.getId().toString(),\n                               \"intentosFallidos\", usuario.getIntentosFallidos())));\n            }\n            throw new CredencialesInvalidasException();\n        }\n\n        if (usuario.debeCambiarPassword()) {\n            throw new CambioPasswordRequeridoException();\n        }\n        usuario.registrarLoginExitoso();\n        contar(\"usuarios.login.exitosos\");\n        return repositorio.guardar(usuario);\n    }\n\n    /**\n     * Sustituye la contraseña temporal por una definitiva. Exige la contraseña temporal actual.\n     * No emite tokens: después de cambiarla, el usuario inicia sesión normalmente.\n     */\n    @Transactional(noRollbackFor = CredencialesInvalidasException.class)\n    public void cambiarPasswordTemporal(String correo, String passwordActual, String passwordNueva) {\n        Instant ahora = Instant.now(reloj);\n        Usuario usuario = repositorio.buscarPorCorreo(Usuario.normalizarCorreo(correo))\n                .orElseThrow(CredencialesInvalidasException::new);\n        usuario.verificarAcceso(ahora);\n        if (!passwordEncoder.matches(passwordActual == null ? \"\" : passwordActual, usuario.getPasswordHash())) {\n            boolean bloqueadoAhora = usuario.registrarIntentoFallido(ahora);\n            repositorio.guardar(usuario);\n            if (bloqueadoAhora) {\n                publicador.publicar(new EventoDominio(\n                        EVENTO_USUARIO_BLOQUEADO,\n                        usuario.getId().toString(),\n                        Map.of(\"usuarioId\", usuario.getId().toString(),\n                               \"intentosFallidos\", usuario.getIntentosFallidos())));\n            }\n            throw new CredencialesInvalidasException();\n        }\n        if (passwordEncoder.matches(passwordNueva, usuario.getPasswordHash())) {\n            throw new ReglaDeNegocioException(\"La nueva contraseña debe ser distinta a la temporal\");\n        }\n        usuario.cambiarPasswordTemporal(passwordEncoder.encode(passwordNueva));\n        repositorio.guardar(usuario);\n    }\n\n    /** Reemplaza los roles del usuario y registra la operación con su motivo. */\n    @Transactional\n    public Usuario asignarRoles(UUID id, Set<Rol> nuevosRoles, String motivo) {\n        Usuario usuario = obtener(id);\n        List<String> anteriores = nombres(usuario.getRoles());\n        usuario.asignarRoles(nuevosRoles, motivo);\n        Usuario guardado = repositorio.guardar(usuario);\n        publicador.publicar(new EventoDominio(\n                EVENTO_ROL_ASIGNADO,\n                id.toString(),\n                Map.of(\"usuarioId\", id.toString(),\n                       \"rolesAnteriores\", anteriores,\n                       \"rolesNuevos\", nombres(guardado.getRoles()),\n                       \"motivo\", motivo)));\n        return guardado;\n    }\n\n    /** Asigna el área del usuario y registra la operación con su motivo. */\n    @Transactional\n    public Usuario asignarArea(UUID id, String area, String motivo) {\n        Usuario usuario = obtener(id);\n        String anterior = usuario.getArea() == null ? \"\" : usuario.getArea();\n        usuario.asignarArea(area, motivo);\n        Usuario guardado = repositorio.guardar(usuario);\n        publicador.publicar(new EventoDominio(\n                EVENTO_AREA_ASIGNADA,\n                id.toString(),\n                Map.of(\"usuarioId\", id.toString(),\n                       \"areaAnterior\", anterior,\n                       \"areaNueva\", guardado.getArea(),\n                       \"motivo\", motivo)));\n        return guardado;\n    }\n\n    /** Da de baja al usuario de forma definitiva. */\n    @Transactional\n    public Usuario darDeBaja(UUID id) {\n        Usuario usuario = obtener(id);\n        usuario.darDeBaja();\n        contar(\"usuarios.bajas\");\n        return repositorio.guardar(usuario);\n    }\n\n    /** Últimos 15 usuarios, del más reciente al más antiguo. Solo para ADMIN. */\n    @Transactional(readOnly = true)\n    public List<Usuario> listarRecientes() {\n        return repositorio.listarRecientes(15);\n    }\n\n    /** Devuelve un usuario por id o lanza RecursoNoEncontradoException. */\n    @Transactional(readOnly = true)\n    public Usuario obtener(UUID id) {\n        return repositorio.buscarPorId(id)\n                .orElseThrow(() -> new RecursoNoEncontradoException(\"Usuario no encontrado\"));\n    }\n\n    /** Convierte roles en sus nombres, para eventos y registros. */\n    private static List<String> nombres(Collection<Rol> roles) {\n        return roles.stream().map(Enum::name).sorted().collect(Collectors.toList());\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/usuarios_accesos/config/AdministradorInicialConfig.java": "package com.mx.josesaid.develop.usuarios_accesos.config;\n\nimport com.mx.josesaid.develop.usuarios_accesos.application.UsuarioService;\nimport com.mx.josesaid.develop.usuarios_accesos.domain.Rol;\nimport com.mx.josesaid.develop.usuarios_accesos.domain.Usuario;\nimport com.mx.josesaid.develop.usuarios_accesos.domain.UsuarioRepositorio;\nimport java.util.Set;\nimport org.slf4j.Logger;\nimport org.slf4j.LoggerFactory;\nimport org.springframework.boot.ApplicationArguments;\nimport org.springframework.boot.ApplicationRunner;\nimport org.springframework.context.annotation.Bean;\nimport org.springframework.context.annotation.Configuration;\n\n/**\n * Crea el primer administrador al arrancar, si se configura con variables de entorno.\n *\n * <p>Resuelve el arranque en frío: crear usuarios requiere un token de ADMIN, y sin un\n * administrador previo nadie podría crearlo. Es idempotente: si el correo ya existe, no hace nada.\n * La contraseña nunca se registra en logs.\n */\n@Configuration\npublic class AdministradorInicialConfig {\n\n    private static final Logger LOG = LoggerFactory.getLogger(AdministradorInicialConfig.class);\n\n    /** Crea el administrador inicial al arrancar, si las variables de entorno lo configuran. Si el correo ya existe, no hace nada. */\n    @Bean\n    ApplicationRunner administradorInicial(UsuarioService servicio, UsuarioRepositorio repositorio,\n                                           PropiedadesAdministradorInicial propiedades) {\n        return (ApplicationArguments args) -> {\n            String correo = propiedades.correo();\n            if (correo == null || correo.isBlank()) {\n                return; // no configurado: no se crea nada\n            }\n            String correoNormalizado = Usuario.normalizarCorreo(correo);\n            if (repositorio.existePorCorreo(correoNormalizado)) {\n                return;\n            }\n            servicio.crear(correoNormalizado, \"Administrador inicial\", propiedades.password(), Set.of(Rol.ADMIN));\n            LOG.info(\"Administrador inicial creado\");\n        };\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/usuarios_accesos/config/ClavesJwt.java": "package com.mx.josesaid.develop.usuarios_accesos.config;\n\nimport com.nimbusds.jose.jwk.RSAKey;\nimport java.security.GeneralSecurityException;\nimport java.security.KeyFactory;\nimport java.security.interfaces.RSAPrivateCrtKey;\nimport java.security.interfaces.RSAPublicKey;\nimport java.security.spec.PKCS8EncodedKeySpec;\nimport java.security.spec.RSAPublicKeySpec;\nimport java.security.spec.X509EncodedKeySpec;\nimport java.util.Base64;\n\n/**\n * Carga las claves RSA que firman y validan los tokens. Solo este servicio conoce la clave privada;\n * los demás servicios validan con las claves públicas publicadas en /.well-known/jwks.json.\n */\npublic final class ClavesJwt {\n\n    /** Identificador por defecto de la clave; viaja en el encabezado \"kid\" de cada token. */\n    public static final String KID_POR_DEFECTO = \"empresa-usuarios-1\";\n\n    /** Clase de utilidad; no se instancia. */\n    private ClavesJwt() {\n    }\n\n    /** Devuelve el kid configurado, o el valor por defecto si no se configuró ninguno. */\n    public static String kid(String kidConfigurado) {\n        return kidConfigurado == null || kidConfigurado.isBlank() ? KID_POR_DEFECTO : kidConfigurado.trim();\n    }\n\n    /** Falla al arrancar si la clave falta o no es RSA válida: no se firma con una clave por defecto. */\n    public static RSAKey desdeBase64(String clavePrivadaBase64, String kidConfigurado) {\n        if (clavePrivadaBase64 == null || clavePrivadaBase64.isBlank()) {\n            throw new IllegalStateException(\"usuarios.jwt.clave-privada es obligatoria\");\n        }\n        try {\n            byte[] der = Base64.getDecoder().decode(clavePrivadaBase64.replaceAll(\"\\\\s\", \"\"));\n            KeyFactory fabrica = KeyFactory.getInstance(\"RSA\");\n            RSAPrivateCrtKey privada = (RSAPrivateCrtKey) fabrica.generatePrivate(new PKCS8EncodedKeySpec(der));\n            RSAPublicKey publica = (RSAPublicKey) fabrica.generatePublic(\n                    new RSAPublicKeySpec(privada.getModulus(), privada.getPublicExponent()));\n            return new RSAKey.Builder(publica).privateKey(privada).keyID(kid(kidConfigurado)).build();\n        } catch (GeneralSecurityException | IllegalArgumentException e) {\n            throw new IllegalStateException(\"usuarios.jwt.clave-privada no es una clave RSA válida (PKCS#8 en Base64)\", e);\n        }\n    }\n\n    /**\n     * Clave pública anterior de una rotación. Sigue validando los tokens emitidos antes del cambio\n     * hasta que expiren; después se quita de la configuración.\n     */\n    public static RSAKey publicaAnterior(String clavePublicaBase64, String kidAnterior, String kidActual) {\n        if (clavePublicaBase64 == null || clavePublicaBase64.isBlank()) {\n            throw new IllegalStateException(\"usuarios.jwt.clave-publica-anterior está vacía\");\n        }\n        if (kidAnterior == null || kidAnterior.isBlank()) {\n            throw new IllegalStateException(\"usuarios.jwt.kid-anterior es obligatorio cuando hay clave-publica-anterior\");\n        }\n        if (kidAnterior.trim().equals(kidActual)) {\n            throw new IllegalStateException(\"usuarios.jwt.kid-anterior debe ser distinto de usuarios.jwt.kid\");\n        }\n        try {\n            byte[] der = Base64.getDecoder().decode(clavePublicaBase64.replaceAll(\"\\\\s\", \"\"));\n            RSAPublicKey publica = (RSAPublicKey) KeyFactory.getInstance(\"RSA\")\n                    .generatePublic(new X509EncodedKeySpec(der));\n            return new RSAKey.Builder(publica).keyID(kidAnterior.trim()).build();\n        } catch (GeneralSecurityException | IllegalArgumentException e) {\n            throw new IllegalStateException(\"usuarios.jwt.clave-publica-anterior no es una clave pública RSA válida (X.509 en Base64)\", e);\n        }\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/usuarios_accesos/config/CryptoConfig.java": "package com.mx.josesaid.develop.usuarios_accesos.config;\n\nimport com.mx.josesaid.develop.usuarios_accesos.infrastructure.crypto.ClavesCripto;\nimport java.util.Arrays;\nimport java.util.Base64;\nimport java.util.HashMap;\nimport java.util.Map;\nimport org.springframework.beans.factory.annotation.Value;\nimport org.springframework.context.annotation.Configuration;\n\n/** Valida las claves al arrancar. Si faltan, no miden 32 bytes o son iguales, el servicio no inicia. */\n@Configuration\npublic class CryptoConfig {\n\n    private static final int LONGITUD_CLAVE = 32;\n    private static final int VERSION_UNICA = 1;\n\n    /** Recibe la clave de cifrado única y la lista de claves por versión, desde la configuración. */\n    public CryptoConfig(@Value(\"${USUARIOS_CIFRADO_CLAVE:}\") String claveCifrado,\n                        @Value(\"${USUARIOS_CIFRADO_CLAVES:}\") String clavesCifrado,\n                        @Value(\"${USUARIOS_CIFRADO_VERSION_ACTIVA:1}\") int versionActiva,\n                        @Value(\"${USUARIOS_INDICE_CLAVE:}\") String claveIndice) {\n        Map<Integer, byte[]> cifrado = clavesCifrado(claveCifrado, clavesCifrado);\n        byte[] indice = decodificar(\"USUARIOS_INDICE_CLAVE\", claveIndice);\n        for (byte[] clave : cifrado.values()) {\n            if (Arrays.equals(clave, indice)) {\n                throw new IllegalStateException(\"Las claves de cifrado y la de índice deben ser distintas\");\n            }\n        }\n        ClavesCripto.configurar(cifrado, versionActiva, indice);\n    }\n\n    /** Construye el mapa de claves de cifrado por versión a partir de la configuración. */\n    private static Map<Integer, byte[]> clavesCifrado(String claveUnica, String lista) {\n        Map<Integer, byte[]> claves = new HashMap<>();\n        if (lista != null && !lista.isBlank()) {\n            for (String entrada : lista.split(\",\")) {\n                String[] partes = entrada.trim().split(\":\", 2);\n                if (partes.length != 2) {\n                    throw new IllegalStateException(\"USUARIOS_CIFRADO_CLAVES debe tener el formato N:base64,N:base64\");\n                }\n                int numero = Integer.parseInt(partes[0].trim());\n                if (claves.put(numero, decodificar(\"USUARIOS_CIFRADO_CLAVES versión \" + numero, partes[1])) != null) {\n                    throw new IllegalStateException(\"La versión \" + numero + \" de clave aparece más de una vez\");\n                }\n            }\n        } else {\n            claves.put(VERSION_UNICA, decodificar(\"USUARIOS_CIFRADO_CLAVE\", claveUnica));\n        }\n        return claves;\n    }\n\n    /** Decodifica una clave en Base64 y valida su longitud. */\n    private static byte[] decodificar(String nombre, String valor) {\n        if (valor == null || valor.isBlank()) {\n            throw new IllegalStateException(\"Falta \" + nombre);\n        }\n        byte[] clave = Base64.getDecoder().decode(valor.trim());\n        if (clave.length != LONGITUD_CLAVE) {\n            throw new IllegalStateException(nombre + \" debe ser de 32 bytes en Base64; recibió \" + clave.length);\n        }\n        return clave;\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/usuarios_accesos/config/PropiedadesAdministradorInicial.java": "package com.mx.josesaid.develop.usuarios_accesos.config;\n\nimport org.springframework.boot.context.properties.ConfigurationProperties;\n\n/**\n * Administrador inicial opcional, enlazado desde {@code usuarios.admin-inicial}.\n *\n * @param correo   correo del administrador; vacío = no crear\n * @param password contraseña inicial; cámbiala tras el primer inicio de sesión\n */\n@ConfigurationProperties(prefix = \"usuarios.admin-inicial\")\npublic record PropiedadesAdministradorInicial(String correo, String password) {\n}\n", "src/main/java/com/mx/josesaid/develop/usuarios_accesos/config/PropiedadesJwt.java": "package com.mx.josesaid.develop.usuarios_accesos.config;\n\nimport java.time.Duration;\nimport org.springframework.boot.context.properties.ConfigurationProperties;\n\n/**\n * Propiedades del emisor de tokens, enlazadas desde {@code usuarios.jwt}.\n *\n * @param clavePrivada         clave RSA privada en PKCS#8 DER codificada en Base64; nunca se registra en logs\n * @param duracion             vida del token de acceso\n * @param emisor               valor del claim {@code iss}\n * @param kid                  identificador de la clave actual (encabezado \"kid\")\n * @param clavePublicaAnterior clave pública anterior en X.509 DER Base64; solo durante una rotación\n * @param kidAnterior          identificador de la clave pública anterior\n */\n@ConfigurationProperties(prefix = \"usuarios.jwt\")\npublic record PropiedadesJwt(String clavePrivada, Duration duracion, String emisor,\n                             String kid, String clavePublicaAnterior, String kidAnterior) {\n}\n", "src/main/java/com/mx/josesaid/develop/usuarios_accesos/config/RelojConfig.java": "package com.mx.josesaid.develop.usuarios_accesos.config;\n\nimport java.time.Clock;\nimport org.springframework.context.annotation.Bean;\nimport org.springframework.context.annotation.Configuration;\n\n/** Reloj en UTC. Inyectarlo permite probar las reglas de tiempo sin depender de la hora real. */\n@Configuration\npublic class RelojConfig {\n\n    /** Reloj del sistema en UTC, usado para todas las fechas de usuarios y sesiones. */\n    @Bean\n    Clock reloj() {\n        return Clock.systemUTC();\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/usuarios_accesos/config/SeguridadConfig.java": "package com.mx.josesaid.develop.usuarios_accesos.config;\n\nimport com.mx.josesaid.develop.usuarios_accesos.seguridad.EntradaNoAutorizada;\n\nimport com.mx.josesaid.develop.usuarios_accesos.seguridad.RevocacionSesiones;\nimport com.mx.josesaid.develop.usuarios_accesos.seguridad.ValidadorRevocacion;\nimport org.springframework.security.oauth2.core.DelegatingOAuth2TokenValidator;\nimport org.springframework.security.oauth2.jwt.JwtValidators;\n\nimport com.nimbusds.jose.jwk.JWK;\nimport com.nimbusds.jose.jwk.JWKSet;\nimport com.nimbusds.jose.proc.SecurityContext;\nimport java.util.ArrayList;\nimport java.util.List;\nimport com.nimbusds.jose.jwk.RSAKey;\nimport com.nimbusds.jose.jwk.source.ImmutableJWKSet;\nimport org.springframework.context.annotation.Bean;\nimport org.springframework.context.annotation.Configuration;\nimport org.springframework.security.config.annotation.method.configuration.EnableMethodSecurity;\nimport org.springframework.security.config.annotation.web.builders.HttpSecurity;\nimport org.springframework.security.config.annotation.web.configuration.EnableWebSecurity;\nimport org.springframework.security.config.http.SessionCreationPolicy;\nimport org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder;\nimport org.springframework.security.crypto.password.PasswordEncoder;\nimport org.springframework.security.oauth2.jwt.JwtDecoder;\nimport org.springframework.security.oauth2.jwt.JwtEncoder;\nimport org.springframework.security.oauth2.jwt.NimbusJwtDecoder;\nimport org.springframework.security.oauth2.jwt.NimbusJwtEncoder;\nimport org.springframework.security.oauth2.server.resource.authentication.JwtAuthenticationConverter;\nimport org.springframework.security.oauth2.server.resource.authentication.JwtGrantedAuthoritiesConverter;\nimport org.springframework.security.web.SecurityFilterChain;\n\n/**\n * Seguridad del servicio: API sin estado, JWT como resource server y autorización por rol.\n *\n * <p>Solo el login y el health son públicos. Todo lo demás exige un token válido.\n */\n@Configuration\n@EnableWebSecurity\n@EnableMethodSecurity\npublic class SeguridadConfig {\n\n    /** Cadena de seguridad: deja abiertos el inicio de sesión, la renovación, el cambio de contraseña temporal, el cierre de una sesión y las claves públicas. El resto exige JWT válido. */\n    @Bean\n    SecurityFilterChain cadenaSeguridad(HttpSecurity http) throws Exception {\n        http\n            .csrf(csrf -> csrf.disable()) // API sin cookies de sesión: no aplica CSRF\n            .sessionManagement(sesion -> sesion.sessionCreationPolicy(SessionCreationPolicy.STATELESS))\n            .authorizeHttpRequests(auth -> auth\n                .requestMatchers(\"/v1/auth/login\", \"/v1/auth/refresh\", \"/v1/auth/logout\", \"/v1/auth/cambiar-password-inicial\", \"/actuator/health\", \"/actuator/health/**\", \"/actuator/prometheus\", \"/.well-known/jwks.json\").permitAll()\n                .anyRequest().authenticated())\n            .oauth2ResourceServer(oauth -> oauth.authenticationEntryPoint(new EntradaNoAutorizada()).jwt(jwt -> jwt.jwtAuthenticationConverter(convertidorJwt())));\n        return http.build();\n    }\n\n    /** Convierte el claim {@code roles} en autoridades {@code ROLE_*}. */\n    @Bean\n    JwtAuthenticationConverter convertidorJwt() {\n        JwtGrantedAuthoritiesConverter autoridades = new JwtGrantedAuthoritiesConverter();\n        autoridades.setAuthoritiesClaimName(\"roles\");\n        autoridades.setAuthorityPrefix(\"ROLE_\");\n        JwtAuthenticationConverter convertidor = new JwtAuthenticationConverter();\n        convertidor.setJwtGrantedAuthoritiesConverter(autoridades);\n        return convertidor;\n    }\n\n    /** Clave RSA (privada y pública) cargada desde usuarios.jwt.clave-privada. */\n    @Bean\n    RSAKey claveRsa(PropiedadesJwt propiedades) {\n        return ClavesJwt.desdeBase64(propiedades.clavePrivada(), propiedades.kid());\n    }\n\n    /** Claves públicas que validan los tokens: la actual y, durante una rotación, la anterior. */\n    @Bean\n    JWKSet clavesPublicas(RSAKey claveRsa, PropiedadesJwt propiedades) {\n        List<JWK> claves = new ArrayList<>();\n        claves.add(claveRsa.toPublicJWK());\n        if (propiedades.clavePublicaAnterior() != null && !propiedades.clavePublicaAnterior().isBlank()) {\n            claves.add(ClavesJwt.publicaAnterior(propiedades.clavePublicaAnterior(),\n                    propiedades.kidAnterior(), claveRsa.getKeyID()));\n        }\n        return new JWKSet(claves);\n    }\n\n    /** Valida los tokens por kid con las claves publicadas; este mismo servicio también es resource server. */\n    @Bean\n    JwtDecoder jwtDecoder(JWKSet clavesPublicas, RevocacionSesiones revocaciones) {\n        var decoder = NimbusJwtDecoder.withJwkSource(new ImmutableJWKSet<SecurityContext>(clavesPublicas)).build();\n        decoder.setJwtValidator(new DelegatingOAuth2TokenValidator<>(JwtValidators.createDefault(),\n                new ValidadorRevocacion(revocaciones)));\n        return decoder;\n    }\n\n    /** Firma los tokens con la clave privada (RS256). */\n    @Bean\n    JwtEncoder jwtEncoder(RSAKey claveRsa) {\n        return new NimbusJwtEncoder(new ImmutableJWKSet<>(new JWKSet(claveRsa)));\n    }\n\n    /** Codificador de contraseñas BCrypt. */\n    @Bean\n    PasswordEncoder passwordEncoder() {\n        return new BCryptPasswordEncoder();\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/usuarios_accesos/domain/BloqueoException.java": "package com.mx.josesaid.develop.usuarios_accesos.domain;\n\n/** La cuenta está bloqueada temporalmente por intentos fallidos. Se traduce a HTTP 423. */\npublic class BloqueoException extends RuntimeException {\n    /** Se lanza cuando la cuenta está bloqueada por intentos fallidos. El mensaje indica cuánto esperar. */\n    public BloqueoException(String mensaje) {\n        super(mensaje);\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/usuarios_accesos/domain/CambioPasswordRequeridoException.java": "package com.mx.josesaid.develop.usuarios_accesos.domain;\n\n/**\n * La cuenta tiene una contraseña temporal pendiente de cambio. Se traduce a HTTP 403.\n */\npublic class CambioPasswordRequeridoException extends RuntimeException {\n    /** Se lanza cuando la contraseña es temporal y debe cambiarse antes de iniciar sesión. */\n    public CambioPasswordRequeridoException() {\n        super(\"Debe cambiar su contraseña temporal antes de iniciar sesión\");\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/usuarios_accesos/domain/ConflictoException.java": "package com.mx.josesaid.develop.usuarios_accesos.domain;\n\n/** Ya existe un recurso con el mismo identificador único. Se traduce a HTTP 409. */\npublic class ConflictoException extends RuntimeException {\n    /** Se lanza cuando la operación choca con el estado actual. Se responde como conflicto. */\n    public ConflictoException(String mensaje) {\n        super(mensaje);\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/usuarios_accesos/domain/CredencialesInvalidasException.java": "package com.mx.josesaid.develop.usuarios_accesos.domain;\n\n/**\n * Correo o contraseña incorrectos, o cuenta dada de baja.\n * Se usa el mismo mensaje en todos los casos para no revelar qué usuarios existen. Se traduce a HTTP 401.\n */\npublic class CredencialesInvalidasException extends RuntimeException {\n    /** Se lanza cuando el correo o la contraseña no son válidos. Usa un mensaje genérico para no revelar cuál de los dos falló. */\n    public CredencialesInvalidasException() {\n        super(\"Correo o contraseña incorrectos\");\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/usuarios_accesos/domain/EstatusUsuario.java": "package com.mx.josesaid.develop.usuarios_accesos.domain;\n\n/** Estados del ciclo de vida de un usuario. BAJA es definitiva. */\npublic enum EstatusUsuario {\n    ACTIVO,\n    BLOQUEADO,\n    BAJA\n}\n", "src/main/java/com/mx/josesaid/develop/usuarios_accesos/domain/RecursoNoEncontradoException.java": "package com.mx.josesaid.develop.usuarios_accesos.domain;\n\n/** El recurso solicitado no existe. Se traduce a HTTP 404. */\npublic class RecursoNoEncontradoException extends RuntimeException {\n    /** Se lanza cuando no existe el recurso pedido. */\n    public RecursoNoEncontradoException(String mensaje) {\n        super(mensaje);\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/usuarios_accesos/domain/RefreshToken.java": "package com.mx.josesaid.develop.usuarios_accesos.domain;\n\nimport java.time.Instant;\nimport java.util.UUID;\n\n/**\n * Refresh token de una sesión. Guarda el hash del token, no el token. Es inmutable: marcar\n * como usado produce una copia.\n  * @param id identificador único del registro, de tipo {@code UUID}.\n  * @param usuarioId identificador del usuario, de tipo {@code UUID}.\n  * @param familiaId identificador del familia, de tipo {@code UUID}.\n  * @param hash hash, de tipo {@code String}.\n  * @param expiraUtc expira utc, de tipo {@code Instant}.\n  * @param usadoUtc usado utc, de tipo {@code Instant}.\n  * @param revocadoUtc revocado utc, de tipo {@code Instant}.\n */\npublic record RefreshToken(UUID id, UUID usuarioId, UUID familiaId, String hash,\n                           Instant expiraUtc, Instant usadoUtc, Instant revocadoUtc) {\n\n    /** Vigente: no usado, no revocado y no vencido. */\n    public boolean activo(Instant ahora) {\n        return usadoUtc == null && revocadoUtc == null && ahora.isBefore(expiraUtc);\n    }\n\n    /** Devuelve una copia marcada como usada en el instante indicado. El objeto original no cambia. */\n    public RefreshToken comoUsado(Instant ahora) {\n        return new RefreshToken(id, usuarioId, familiaId, hash, expiraUtc, ahora, revocadoUtc);\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/usuarios_accesos/domain/RefreshTokenRepositorio.java": "package com.mx.josesaid.develop.usuarios_accesos.domain;\n\nimport java.time.Instant;\nimport java.util.Optional;\nimport java.util.UUID;\n\n/** Puerto de persistencia de refresh tokens. */\npublic interface RefreshTokenRepositorio {\n\n    /** Inserta o reemplaza por id. */\n    void guardar(RefreshToken token);\n\n    Optional<RefreshToken> buscarPorHash(String hash);\n\n    /** Revoca todos los tokens de la familia que aún no estén revocados. */\n    void revocarFamilia(UUID familiaId, Instant ahora);\n\n    /** Revoca todas las sesiones del usuario. */\n    void revocarTodasDeUsuario(UUID usuarioId, Instant ahora);\n}\n", "src/main/java/com/mx/josesaid/develop/usuarios_accesos/domain/ReglaDeNegocioException.java": "package com.mx.josesaid.develop.usuarios_accesos.domain;\n\n/** Una operación viola una regla de negocio. Se traduce a HTTP 422. */\npublic class ReglaDeNegocioException extends RuntimeException {\n    /** Se lanza cuando una regla de negocio no se cumple. El mensaje se muestra al cliente. */\n    public ReglaDeNegocioException(String mensaje) {\n        super(mensaje);\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/usuarios_accesos/domain/Rol.java": "package com.mx.josesaid.develop.usuarios_accesos.domain;\n\n/** Roles de negocio del sistema. Cada área asigna sus permisos según estos roles. */\npublic enum Rol {\n    ADMIN,\n    FINANZAS,\n    CONTADOR,\n    VENTAS,\n    COMPRAS,\n    ALMACEN,\n    OPERACIONES,\n    CALIDAD,\n    DIRECCION,\n    LEGAL,\n    JEFE_AREA\n}\n", "src/main/java/com/mx/josesaid/develop/usuarios_accesos/domain/Usuario.java": "package com.mx.josesaid.develop.usuarios_accesos.domain;\n\nimport java.time.Duration;\nimport java.time.Instant;\nimport java.util.Collection;\nimport java.util.EnumSet;\nimport java.util.Set;\nimport java.util.UUID;\n\n/**\n * Agregado raíz de identidad.\n *\n * <p>Contiene las reglas de acceso del negocio: bloqueo por intentos fallidos,\n * baja definitiva y asignación de roles con motivo. No depende de Spring, JPA ni Kafka.\n */\npublic class Usuario {\n\n    /** Intentos fallidos consecutivos antes de bloquear la cuenta (propuesta, por validar). */\n    public static final int MAX_INTENTOS_FALLIDOS = 5;\n\n    /** Debe coincidir con los valores del enum Area de reportes-ejecutivos-ms. */\n    public static final java.util.Set<String> AREAS_VALIDAS = java.util.Set.of(\n            \"VENTAS_ATENCION_CLIENTES\", \"FINANZAS_CONTABILIDAD\", \"OPERACIONES\",\n            \"COMPRAS_PROVEEDORES\", \"ADMINISTRACION_LEGAL\", \"DIRECCION_GENERAL\");\n\n    /** Duración del bloqueo temporal (decisión de Said Olano, 2026-11-05). */\n    public static final Duration DURACION_BLOQUEO = Duration.ofMinutes(5);\n\n    private final UUID id;\n    private String correo;\n    private String nombreCompleto;\n    private String passwordHash;\n    private final Set<Rol> roles;\n    private EstatusUsuario estatus;\n    private int intentosFallidos;\n    private Instant bloqueadoHasta;\n    private String area;\n    private boolean debeCambiarPassword;\n\n    /** Constructor privado: los usuarios se crean con sus fábricas, nunca con new. */\n    private Usuario(UUID id, String correo, String nombreCompleto, String passwordHash,\n                    Set<Rol> roles, EstatusUsuario estatus, int intentosFallidos, Instant bloqueadoHasta) {\n        this.id = id;\n        this.correo = correo;\n        this.nombreCompleto = nombreCompleto;\n        this.passwordHash = passwordHash;\n        this.roles = roles;\n        this.estatus = estatus;\n        this.intentosFallidos = intentosFallidos;\n        this.bloqueadoHasta = bloqueadoHasta;\n    }\n\n    /** Crea un usuario activo nuevo. El hash de contraseña llega ya calculado por la capa de aplicación. */\n    public static Usuario crear(String correo, String nombreCompleto, String passwordHash, Collection<Rol> roles) {\n        return new Usuario(\n                UUID.randomUUID(),\n                normalizarCorreo(correo),\n                validarNombre(nombreCompleto),\n                requerido(passwordHash, \"La contraseña es obligatoria\"),\n                validarRoles(roles),\n                EstatusUsuario.ACTIVO,\n                0,\n                null);\n    }\n\n    /** Reconstruye un usuario desde la persistencia, sin volver a validar las reglas de creación. */\n    public static Usuario reconstruir(UUID id, String correo, String nombreCompleto, String passwordHash,\n                                      Collection<Rol> roles, EstatusUsuario estatus,\n                                      int intentosFallidos, Instant bloqueadoHasta) {\n        return new Usuario(id, correo, nombreCompleto, passwordHash,\n                EnumSet.copyOf(roles.isEmpty() ? EnumSet.noneOf(Rol.class) : roles),\n                estatus, intentosFallidos, bloqueadoHasta);\n    }\n\n    /** Normaliza el correo a minúsculas sin espacios y valida su forma básica. */\n    public static String normalizarCorreo(String correo) {\n        String limpio = requerido(correo, \"El correo es obligatorio\").trim().toLowerCase();\n        if (!limpio.contains(\"@\")) {\n            throw new ReglaDeNegocioException(\"El correo no tiene un formato válido\");\n        }\n        return limpio;\n    }\n\n    /**\n     * Verifica que la cuenta pueda intentar iniciar sesión.\n     * Una cuenta bloqueada cuyo plazo ya venció se desbloquea aquí.\n     */\n    public void verificarAcceso(Instant ahora) {\n        if (estatus == EstatusUsuario.BAJA) {\n            // Se responde igual que una credencial incorrecta para no revelar la baja\n            throw new CredencialesInvalidasException();\n        }\n        if (estatus == EstatusUsuario.BLOQUEADO) {\n            if (bloqueadoHasta != null && ahora.isBefore(bloqueadoHasta)) {\n                throw new BloqueoException(\"La cuenta está bloqueada temporalmente. Intenta más tarde.\");\n            }\n            estatus = EstatusUsuario.ACTIVO;\n            intentosFallidos = 0;\n            bloqueadoHasta = null;\n        }\n    }\n\n    /**\n     * Registra una contraseña incorrecta.\n     *\n     * @return true solo cuando este intento provoca el bloqueo de la cuenta\n     */\n    public boolean registrarIntentoFallido(Instant ahora) {\n        intentosFallidos++;\n        if (intentosFallidos >= MAX_INTENTOS_FALLIDOS) {\n            estatus = EstatusUsuario.BLOQUEADO;\n            bloqueadoHasta = ahora.plus(DURACION_BLOQUEO);\n            return true;\n        }\n        return false;\n    }\n\n    /** Reinicia los contadores tras un inicio de sesión exitoso. */\n    public void registrarLoginExitoso() {\n        intentosFallidos = 0;\n        bloqueadoHasta = null;\n        estatus = EstatusUsuario.ACTIVO;\n    }\n\n    /**\n     * Reemplaza los roles del usuario. El motivo es obligatorio para auditoría.\n     */\n    public void asignarRoles(Collection<Rol> nuevos, String motivo) {\n        if (estatus == EstatusUsuario.BAJA) {\n            throw new ReglaDeNegocioException(\"No se pueden asignar roles a un usuario dado de baja\");\n        }\n        requerido(motivo, \"El motivo del cambio de roles es obligatorio\");\n        Set<Rol> validados = validarRoles(nuevos);\n        if (validados.contains(Rol.JEFE_AREA) && (area == null || area.isBlank())) {\n            throw new ReglaDeNegocioException(\"Asigne un área al usuario antes del rol JEFE_AREA\");\n        }\n        roles.clear();\n        roles.addAll(validados);\n    }\n\n    /**\n     * Asigna el área del usuario. Un JEFE_AREA solo consulta indicadores de esta área.\n     * El motivo es obligatorio para auditoría.\n     */\n    public void asignarArea(String nuevaArea, String motivo) {\n        if (estatus == EstatusUsuario.BAJA) {\n            throw new ReglaDeNegocioException(\"No se puede asignar área a un usuario dado de baja\");\n        }\n        String validada = requerido(nuevaArea, \"El área es obligatoria\");\n        if (!AREAS_VALIDAS.contains(validada)) {\n            throw new ReglaDeNegocioException(\"Área no válida: \" + validada);\n        }\n        requerido(motivo, \"El motivo del cambio de área es obligatorio\");\n        area = validada;\n    }\n\n    /** Fija el área al reconstruir desde persistencia. */\n    public Usuario conArea(String area) {\n        this.area = area;\n        return this;\n    }\n\n    /** Marca la contraseña como temporal: la cuenta no podrá iniciar sesión hasta cambiarla. */\n    public void marcarPasswordTemporal() {\n        this.debeCambiarPassword = true;\n    }\n\n    /** Reconstruye el indicador desde la persistencia. */\n    public Usuario conDebeCambiarPassword(boolean valor) {\n        this.debeCambiarPassword = valor;\n        return this;\n    }\n\n    /** Indica si la contraseña es temporal y debe cambiarse antes de iniciar sesión. */\n    public boolean debeCambiarPassword() {\n        return debeCambiarPassword;\n    }\n\n    /** Sustituye la contraseña temporal por una definitiva y quita el indicador. */\n    public void cambiarPasswordTemporal(String nuevoHash) {\n        if (!debeCambiarPassword) {\n            throw new ReglaDeNegocioException(\"La contraseña no está pendiente de cambio\");\n        }\n        this.passwordHash = requerido(nuevoHash, \"La contraseña es obligatoria\");\n        this.debeCambiarPassword = false;\n    }\n\n    /** Da de baja al usuario. Es definitivo: no se puede reactivar y hay que crear uno nuevo. También quita el bloqueo temporal. */\n    public void darDeBaja() {\n        if (estatus == EstatusUsuario.BAJA) {\n            throw new ReglaDeNegocioException(\"El usuario ya está dado de baja\");\n        }\n        estatus = EstatusUsuario.BAJA;\n        intentosFallidos = 0;\n        bloqueadoHasta = null;\n    }\n\n    /** Valida que haya al menos un rol y devuelve una copia sin duplicados. */\n    private static Set<Rol> validarRoles(Collection<Rol> roles) {\n        if (roles == null || roles.isEmpty()) {\n            throw new ReglaDeNegocioException(\"Debe asignar al menos un rol\");\n        }\n        return EnumSet.copyOf(roles);\n    }\n\n    /** Valida y recorta el nombre completo. */\n    private static String validarNombre(String nombre) {\n        return requerido(nombre, \"El nombre completo es obligatorio\").trim();\n    }\n\n    /** Rechaza un valor vacío con el mensaje indicado. */\n    private static String requerido(String valor, String mensaje) {\n        if (valor == null || valor.isBlank()) {\n            throw new ReglaDeNegocioException(mensaje);\n        }\n        return valor;\n    }\n\n    /** Devuelve el identificador. */\n    public UUID getId() {\n        return id;\n    }\n\n    /** Devuelve el correo. */\n    public String getCorreo() {\n        return correo;\n    }\n\n    /** Devuelve el nombre completo. */\n    public String getNombreCompleto() {\n        return nombreCompleto;\n    }\n\n    /** Devuelve el hash de la contraseña, nunca la contraseña en claro. */\n    public String getPasswordHash() {\n        return passwordHash;\n    }\n\n    /** Copia defensiva: el conjunto interno solo cambia mediante {@link #asignarRoles}. */\n    public Set<Rol> getRoles() {\n        return EnumSet.copyOf(roles.isEmpty() ? EnumSet.noneOf(Rol.class) : roles);\n    }\n\n    /** Devuelve el área. */\n    public String getArea() {\n        return area;\n    }\n\n    /** Devuelve el estatus. */\n    public EstatusUsuario getEstatus() {\n        return estatus;\n    }\n\n    /** Devuelve los intentos fallidos consecutivos. */\n    public int getIntentosFallidos() {\n        return intentosFallidos;\n    }\n\n    /** Devuelve hasta cuándo está bloqueada la cuenta, o nulo si no lo está. */\n    public Instant getBloqueadoHasta() {\n        return bloqueadoHasta;\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/usuarios_accesos/domain/UsuarioRepositorio.java": "package com.mx.josesaid.develop.usuarios_accesos.domain;\n\nimport java.util.Optional;\nimport java.util.UUID;\n\n/** Puerto de persistencia del agregado Usuario. La implementación vive en infraestructura. */\npublic interface UsuarioRepositorio {\n\n    Usuario guardar(Usuario usuario);\n\n    Optional<Usuario> buscarPorId(UUID id);\n\n    /** Recibe el correo ya normalizado. */\n    Optional<Usuario> buscarPorCorreo(String correoNormalizado);\n\n    /** Recibe el correo ya normalizado. */\n    boolean existePorCorreo(String correoNormalizado);\n\n    /** Usuarios más recientes primero, hasta {@code limite}. */\n    java.util.List<Usuario> listarRecientes(int limite);\n}\n", "src/main/java/com/mx/josesaid/develop/usuarios_accesos/infrastructure/crypto/CampoCifradoConverter.java": "package com.mx.josesaid.develop.usuarios_accesos.infrastructure.crypto;\n\nimport jakarta.persistence.AttributeConverter;\nimport jakarta.persistence.Converter;\nimport java.nio.ByteBuffer;\nimport java.nio.charset.StandardCharsets;\nimport java.security.GeneralSecurityException;\nimport java.security.SecureRandom;\nimport java.util.Arrays;\nimport java.util.Base64;\nimport java.util.regex.Matcher;\nimport java.util.regex.Pattern;\nimport javax.crypto.Cipher;\nimport javax.crypto.spec.GCMParameterSpec;\n\n/**\n * Cifra un campo con AES-256-GCM.\n * <p>\n * Formato en la columna: {@code v<N>:Base64( IV de 12 bytes || texto cifrado+tag )}, donde N es la versión\n * de la clave con la que se cifró. Los valores sin prefijo son de la versión 1 y se siguen leyendo.\n * Un IV aleatorio por valor: el mismo texto nunca produce el mismo cifrado.\n */\n@Converter\npublic class CampoCifradoConverter implements AttributeConverter<String, String> {\n\n    private static final int LONGITUD_IV = 12;\n    private static final int LONGITUD_TAG_BITS = 128;\n    private static final int VERSION_SIN_PREFIJO = 1;\n    private static final Pattern PREFIJO_VERSION = Pattern.compile(\"^v(\\\\d{1,4}):(.*)$\", Pattern.DOTALL);\n    private static final SecureRandom ALEATORIO = new SecureRandom();\n\n    /** Versión de clave con la que está cifrado un valor de columna. Sin prefijo, la versión 1. */\n    public static int versionDe(String columna) {\n        Matcher prefijo = PREFIJO_VERSION.matcher(columna);\n        return prefijo.matches() ? Integer.parseInt(prefijo.group(1)) : VERSION_SIN_PREFIJO;\n    }\n\n    /** Cifra el texto antes de guardarlo en la base. Los datos personales nunca se guardan en claro. */\n    @Override\n    public String convertToDatabaseColumn(String texto) {\n        if (texto == null) {\n            return null;\n        }\n        int version = ClavesCripto.versionActiva();\n        try {\n            byte[] iv = new byte[LONGITUD_IV];\n            ALEATORIO.nextBytes(iv);\n            Cipher cipher = Cipher.getInstance(\"AES/GCM/NoPadding\");\n            cipher.init(Cipher.ENCRYPT_MODE, ClavesCripto.cifrado(version), new GCMParameterSpec(LONGITUD_TAG_BITS, iv));\n            byte[] cifrado = cipher.doFinal(texto.getBytes(StandardCharsets.UTF_8));\n            byte[] salida = ByteBuffer.allocate(iv.length + cifrado.length).put(iv).put(cifrado).array();\n            return \"v\" + version + \":\" + Base64.getEncoder().encodeToString(salida);\n        } catch (GeneralSecurityException e) {\n            throw new IllegalStateException(\"No se pudo cifrar un campo personal\", e);\n        }\n    }\n\n    /** Descifra el valor leído de la base. Acepta valores sin prefijo de versión. */\n    @Override\n    public String convertToEntityAttribute(String columna) {\n        if (columna == null) {\n            return null;\n        }\n        int version = VERSION_SIN_PREFIJO;\n        String cuerpo = columna;\n        Matcher prefijo = PREFIJO_VERSION.matcher(columna);\n        if (prefijo.matches()) {\n            version = Integer.parseInt(prefijo.group(1));\n            cuerpo = prefijo.group(2);\n        }\n        try {\n            byte[] datos = Base64.getDecoder().decode(cuerpo);\n            byte[] iv = Arrays.copyOfRange(datos, 0, LONGITUD_IV);\n            byte[] cifrado = Arrays.copyOfRange(datos, LONGITUD_IV, datos.length);\n            Cipher cipher = Cipher.getInstance(\"AES/GCM/NoPadding\");\n            cipher.init(Cipher.DECRYPT_MODE, ClavesCripto.cifrado(version), new GCMParameterSpec(LONGITUD_TAG_BITS, iv));\n            return new String(cipher.doFinal(cifrado), StandardCharsets.UTF_8);\n        } catch (GeneralSecurityException e) {\n            throw new IllegalStateException(\"No se pudo descifrar un campo personal\", e);\n        }\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/usuarios_accesos/infrastructure/crypto/ClavesCripto.java": "package com.mx.josesaid.develop.usuarios_accesos.infrastructure.crypto;\n\nimport java.util.HashMap;\nimport java.util.Map;\nimport javax.crypto.SecretKey;\nimport javax.crypto.spec.SecretKeySpec;\n\n/**\n * Claves de cifrado del proceso. Hay una clave AES por versión: se cifra con la versión activa y se\n * descifra con la que indique el prefijo del valor. Las llena CryptoConfig al arrancar, porque los\n * convertidores JPA los crea Hibernate y no Spring.\n */\npublic final class ClavesCripto {\n\n    private static volatile Map<Integer, SecretKey> cifrados = Map.of();\n    private static volatile int versionActiva = 1;\n    private static volatile SecretKey indice;\n\n    /** Clase de utilidad; no se instancia. */\n    private ClavesCripto() {\n    }\n\n    /** Configura una sola clave de cifrado, como versión 1. Ambas deben tener 32 bytes y ser distintas. */\n    public static void configurar(byte[] claveCifrado, byte[] claveIndice) {\n        configurar(Map.of(1, claveCifrado), 1, claveIndice);\n    }\n\n    /** Configura varias versiones de clave de cifrado y cuál usar para cifrar. */\n    public static void configurar(Map<Integer, byte[]> clavesCifrado, int version, byte[] claveIndice) {\n        Map<Integer, SecretKey> claves = new HashMap<>();\n        clavesCifrado.forEach((numero, bytes) -> claves.put(numero, new SecretKeySpec(bytes, \"AES\")));\n        if (!claves.containsKey(version)) {\n            throw new IllegalStateException(\"La versión activa de clave \" + version + \" no está configurada\");\n        }\n        cifrados = Map.copyOf(claves);\n        versionActiva = version;\n        indice = new SecretKeySpec(claveIndice, \"HmacSHA256\");\n    }\n\n    /** Devuelve la versión de clave usada para cifrar nuevos valores. */\n    static int versionActiva() {\n        return versionActiva;\n    }\n\n    /** Devuelve la clave AES de una versión. Falla si esa versión no está configurada. */\n    static SecretKey cifrado(int version) {\n        SecretKey clave = cifrados.get(version);\n        if (clave == null) {\n            throw new IllegalStateException(\"Versión de clave de cifrado no configurada: \" + version);\n        }\n        return clave;\n    }\n\n    /** Devuelve la clave del índice de búsqueda. */\n    static SecretKey indice() {\n        return requerida(indice, \"indice\");\n    }\n\n    /** Verifica que la clave requerida esté configurada antes de usarla. */\n    private static SecretKey requerida(SecretKey clave, String nombre) {\n        if (clave == null) {\n            throw new IllegalStateException(\"La clave de \" + nombre + \" no está configurada\");\n        }\n        return clave;\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/usuarios_accesos/infrastructure/crypto/IndiceCorreo.java": "package com.mx.josesaid.develop.usuarios_accesos.infrastructure.crypto;\n\nimport java.nio.charset.StandardCharsets;\nimport java.security.GeneralSecurityException;\nimport java.util.HexFormat;\nimport java.util.Locale;\nimport javax.crypto.Mac;\n\n/** Índice de búsqueda por correo: HMAC-SHA256 en hexadecimal sobre el correo normalizado. */\npublic final class IndiceCorreo {\n\n    /** Clase de utilidad; no se instancia. */\n    private IndiceCorreo() {\n    }\n\n    /** Calcula el índice de búsqueda del correo normalizado, para buscar sin descifrar todos los usuarios. */\n    public static String de(String correo) {\n        try {\n            Mac mac = Mac.getInstance(\"HmacSHA256\");\n            mac.init(ClavesCripto.indice());\n            byte[] hash = mac.doFinal((\"correo:\" + correo.trim().toLowerCase(Locale.ROOT))\n                    .getBytes(StandardCharsets.UTF_8));\n            return HexFormat.of().formatHex(hash);\n        } catch (GeneralSecurityException e) {\n            throw new IllegalStateException(\"No se pudo calcular el índice de correo\", e);\n        }\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/usuarios_accesos/infrastructure/crypto/MigracionCifradoUsuarios.java": "package com.mx.josesaid.develop.usuarios_accesos.infrastructure.crypto;\n\nimport java.util.List;\nimport java.util.Map;\nimport org.slf4j.Logger;\nimport org.slf4j.LoggerFactory;\nimport org.springframework.boot.ApplicationArguments;\nimport org.springframework.boot.ApplicationRunner;\nimport org.springframework.jdbc.core.JdbcTemplate;\nimport org.springframework.stereotype.Component;\n\n/**\n * Cifra los usuarios que existían en texto plano antes de la migración V5. Es idempotente: solo toca\n * filas sin {@code correo_indice}. No registra correos ni nombres en el log.\n */\n@Component\npublic class MigracionCifradoUsuarios implements ApplicationRunner {\n\n    private static final Logger log = LoggerFactory.getLogger(MigracionCifradoUsuarios.class);\n\n    private final JdbcTemplate jdbc;\n\n    /** Recibe JDBC para leer y actualizar la tabla de usuarios. */\n    public MigracionCifradoUsuarios(JdbcTemplate jdbc) {\n        this.jdbc = jdbc;\n    }\n\n    /** Al arrancar, cifra los usuarios que todavía tienen correo y nombre en claro. Es idempotente y no registra datos personales. */\n    @Override\n    public void run(ApplicationArguments args) {\n        List<Map<String, Object>> pendientes = jdbc.queryForList(\n                \"SELECT id, correo, nombre_completo FROM usuarios WHERE correo_indice IS NULL\");\n        if (pendientes.isEmpty()) {\n            return;\n        }\n        CampoCifradoConverter cifrador = new CampoCifradoConverter();\n        for (Map<String, Object> fila : pendientes) {\n            String correo = (String) fila.get(\"correo\");\n            String nombre = (String) fila.get(\"nombre_completo\");\n            jdbc.update(\n                    \"UPDATE usuarios SET correo = ?, nombre_completo = ?, correo_indice = ? WHERE id = ?\",\n                    cifrador.convertToDatabaseColumn(correo),\n                    cifrador.convertToDatabaseColumn(nombre),\n                    IndiceCorreo.de(correo),\n                    fila.get(\"id\"));\n        }\n        log.info(\"Usuarios cifrados en esta ejecución: {}\", pendientes.size());\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/usuarios_accesos/infrastructure/crypto/RecifradorCamposRunner.java": "package com.mx.josesaid.develop.usuarios_accesos.infrastructure.crypto;\n\nimport java.util.List;\nimport org.slf4j.Logger;\nimport org.slf4j.LoggerFactory;\nimport org.springframework.boot.ApplicationArguments;\nimport org.springframework.boot.ApplicationRunner;\nimport org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;\nimport org.springframework.stereotype.Component;\n\n/**\n * Re-cifra correo y nombre de usuarios a la versión activa. Solo corre con\n * {@code USUARIOS_RECIFRADO_ACTIVO=true}; por defecto no toca datos. Registra solo conteos, nunca valores.\n * El índice {@code correo_indice} no cambia, así que no hace falta recalcularlo.\n */\n@Component\n@ConditionalOnProperty(name = \"USUARIOS_RECIFRADO_ACTIVO\", havingValue = \"true\")\npublic class RecifradorCamposRunner implements ApplicationRunner {\n\n    private static final Logger log = LoggerFactory.getLogger(RecifradorCamposRunner.class);\n    private static final int TAMANO_LOTE = 500;\n    /** Columnas personales de usuarios que se re-cifran a la versión activa. */\n    private static final List<String[]> CAMPOS = List.of(\n            new String[] {\"usuarios\", \"correo\"},\n            new String[] {\"usuarios\", \"nombre_completo\"});\n\n    private final RecifradorJdbc almacen;\n    private final CampoCifradoConverter convertidor = new CampoCifradoConverter();\n\n    /** Recibe el acceso JDBC a las columnas. */\n    public RecifradorCamposRunner(RecifradorJdbc almacen) {\n        this.almacen = almacen;\n    }\n\n    /** Al arrancar, re-cifra las columnas de la lista a la versión activa. */\n    @Override\n    public void run(ApplicationArguments args) {\n        RecifradorPorLotes recifrador = new RecifradorPorLotes(almacen, TAMANO_LOTE,\n                valor -> convertidor.convertToDatabaseColumn(convertidor.convertToEntityAttribute(valor)));\n        for (String[] campo : CAMPOS) {\n            int total = recifrador.ejecutar(campo[0], campo[1]);\n            log.info(\"Campos re-cifrados en {}.{}: {}\", campo[0], campo[1], total);\n        }\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/usuarios_accesos/infrastructure/crypto/RecifradorJdbc.java": "package com.mx.josesaid.develop.usuarios_accesos.infrastructure.crypto;\n\nimport java.util.List;\nimport org.springframework.jdbc.core.JdbcTemplate;\nimport org.springframework.stereotype.Component;\n\n/**\n * Implementación JDBC de {@link RecifradorPorLotes.Almacen}. Tabla y columna vienen de constantes del código\n * (nunca de entrada del usuario), así que se componen en el SQL; los valores van como parámetros.\n */\n@Component\npublic class RecifradorJdbc implements RecifradorPorLotes.Almacen {\n\n    private final JdbcTemplate jdbc;\n\n    /** Acceso JDBC para el re-cifrado por lotes. */\n    public RecifradorJdbc(JdbcTemplate jdbc) {\n        this.jdbc = jdbc;\n    }\n\n    /** Devuelve hasta el límite de filas cuyo valor aún no está en la versión activa. */\n    @Override\n    public List<RecifradorPorLotes.Fila> pendientes(String tabla, String columna, int limite) {\n        String sql = \"SELECT id, \" + columna + \" AS valor FROM \" + tabla\n                + \" WHERE \" + columna + \" IS NOT NULL AND \" + columna + \" NOT LIKE ? ORDER BY id LIMIT ?\";\n        return jdbc.query(sql,\n                (resultado, fila) -> new RecifradorPorLotes.Fila(resultado.getObject(\"id\"), resultado.getString(\"valor\")),\n                \"v\" + ClavesCripto.versionActiva() + \":%\",\n                limite);\n    }\n\n    /** Cambia el valor de una fila solo si aún vale lo que se leyó. */\n    @Override\n    public boolean actualizar(String tabla, String columna, Object id, String valorAnterior, String valorNuevo) {\n        String sql = \"UPDATE \" + tabla + \" SET \" + columna + \" = ? WHERE id = ? AND \" + columna + \" = ?\";\n        return jdbc.update(sql, valorNuevo, id, valorAnterior) == 1;\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/usuarios_accesos/infrastructure/crypto/RecifradorPorLotes.java": "package com.mx.josesaid.develop.usuarios_accesos.infrastructure.crypto;\n\nimport java.util.List;\nimport java.util.function.UnaryOperator;\n\n/**\n * Vuelve a cifrar, por lotes, los valores de una columna que no están en la versión activa de la clave.\n * <p>\n * Es reanudable: solo pide filas pendientes, así que si el proceso se corta, al volver a correrlo continúa\n * donde quedó. Cada fila se actualiza solo si su valor sigue siendo el que se leyó, para no pisar una escritura\n * concurrente de la aplicación.\n */\npublic final class RecifradorPorLotes {\n\n    /**\n     * Fila pendiente: su id y el valor cifrado tal como está en la base.\n     *\n     * @param id identificador único del registro, de tipo {@code Object}.\n     * @param valor valor registrado, de tipo {@code String}.\n     */\n    public record Fila(Object id, String valor) {\n    }\n\n    /** Acceso a la base; la implementación JDBC vive aparte para poder probar la lógica sin base de datos. */\n    public interface Almacen {\n\n        /** Hasta {@code limite} filas con valor no nulo que no están en la versión activa. */\n        List<Fila> pendientes(String tabla, String columna, int limite);\n\n        /** Cambia el valor solo si la columna aún vale {@code valorAnterior}. Devuelve si se cambió. */\n        boolean actualizar(String tabla, String columna, Object id, String valorAnterior, String valorNuevo);\n    }\n\n    private final Almacen almacen;\n    private final int tamanoLote;\n    private final UnaryOperator<String> recifrar;\n\n    /** Recibe el acceso a la base, el tamaño de lote y la función que re-cifra un valor. */\n    public RecifradorPorLotes(Almacen almacen, int tamanoLote, UnaryOperator<String> recifrar) {\n        if (tamanoLote < 1) {\n            throw new IllegalArgumentException(\"El tamaño de lote debe ser al menos 1\");\n        }\n        this.almacen = almacen;\n        this.tamanoLote = tamanoLote;\n        this.recifrar = recifrar;\n    }\n\n    /** Recorre la columna hasta que no queden filas pendientes. Devuelve cuántas se re-cifraron. */\n    public int ejecutar(String tabla, String columna) {\n        int recifradas = 0;\n        while (true) {\n            List<Fila> lote = almacen.pendientes(tabla, columna, tamanoLote);\n            if (lote.isEmpty()) {\n                return recifradas;\n            }\n            for (Fila fila : lote) {\n                String nuevo = recifrar.apply(fila.valor());\n                if (!almacen.actualizar(tabla, columna, fila.id(), fila.valor(), nuevo)) {\n                    throw new IllegalStateException(\n                            \"No se actualizó \" + tabla + \".\" + columna + \" para el id \" + fila.id()\n                                    + \": el valor cambió durante el proceso. Vuelva a ejecutar.\");\n                }\n                recifradas++;\n            }\n        }\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/usuarios_accesos/infrastructure/indicadores/PublicadorIndicadoresUsuarios.java": "package com.mx.josesaid.develop.usuarios_accesos.infrastructure.indicadores;\n\nimport java.math.BigDecimal;\nimport java.time.Clock;\nimport java.time.Instant;\nimport java.time.YearMonth;\nimport java.time.ZoneId;\nimport java.util.concurrent.TimeUnit;\nimport org.slf4j.Logger;\nimport org.slf4j.LoggerFactory;\nimport org.springframework.beans.factory.annotation.Value;\nimport org.springframework.jdbc.core.JdbcTemplate;\nimport org.springframework.kafka.core.KafkaTemplate;\nimport org.springframework.scheduling.annotation.Scheduled;\nimport org.springframework.stereotype.Component;\nimport tools.jackson.databind.ObjectMapper;\n\n/**\n * Publica a reportes-ejecutivos-ms el indicador \"usuarios activos\" del área de administración y legal.\n *\n * <p>Cuenta los usuarios en estatus ACTIVO en este momento. Es una foto del momento, así que solo se\n * publica el mes actual. No pasa por el outbox; si un envío falla, el siguiente ciclo lo corrige.\n */\n@Component\npublic class PublicadorIndicadoresUsuarios {\n\n    private static final Logger log = LoggerFactory.getLogger(PublicadorIndicadoresUsuarios.class);\n\n    /** Valor del enum Area de reportes-ejecutivos-ms. */\n    public static final String AREA = \"ADMINISTRACION_LEGAL\";\n    public static final String NOMBRE = \"usuarios_activos\";\n\n    private static final ZoneId ZONA = ZoneId.of(\"America/Mexico_City\");\n\n    private static final String SQL_ACTIVOS = \"\"\"\n            SELECT COUNT(*)::numeric\n            FROM usuarios\n            WHERE estatus = 'ACTIVO'\n            \"\"\";\n\n    private final JdbcTemplate jdbc;\n    private final KafkaTemplate<String, String> kafka;\n    private final ObjectMapper mapper;\n    private final Clock reloj;\n    private final String topico;\n\n    /** Recibe JDBC para contar y Kafka para publicar. */\n    public PublicadorIndicadoresUsuarios(JdbcTemplate jdbc, KafkaTemplate<String, String> kafka,\n                                         ObjectMapper mapper, Clock reloj,\n                                         @Value(\"${indicadores.topico:indicadores-areas}\") String topico) {\n        this.jdbc = jdbc;\n        this.kafka = kafka;\n        this.mapper = mapper;\n        this.reloj = reloj;\n        this.topico = topico;\n    }\n\n    /** Calcula y publica el indicador de usuarios del periodo para reportes-ejecutivos-ms. */\n    @Scheduled(fixedDelayString = \"${indicadores.intervalo-ms:3600000}\",\n            initialDelayString = \"${indicadores.inicio-ms:30000}\")\n    public void publicar() {\n        String periodo = YearMonth.now(reloj.withZone(ZONA)).toString();\n        BigDecimal valor = jdbc.queryForObject(SQL_ACTIVOS, BigDecimal.class);\n        String payload = mapper.writeValueAsString(\n                new IndicadorEvento(AREA, NOMBRE, periodo, valor, Instant.now(reloj)));\n        try {\n            kafka.send(topico, AREA + \"|\" + NOMBRE + \"|\" + periodo, payload).get(10, TimeUnit.SECONDS);\n            log.info(\"Indicador publicado: {} {} {}\", AREA, NOMBRE, periodo);\n        } catch (InterruptedException ie) {\n            Thread.currentThread().interrupt();\n        } catch (Exception ex) {\n            log.warn(\"No se pudo publicar el indicador {} {}: {}\", NOMBRE, periodo, ex.getClass().getSimpleName());\n        }\n    }\n\n    /**\n     * Formato que espera reportes-ejecutivos-ms (ListenerIndicadores.IndicadorEvento).\n     *\n     * @param area área de negocio a la que pertenece, de tipo {@code String}.\n     * @param nombre nombre descriptivo, de tipo {@code String}.\n     * @param periodo periodo de referencia (por ejemplo, año y mes), de tipo {@code String}.\n     * @param valor valor registrado, de tipo {@code BigDecimal}.\n     * @param fuenteActualizadaUtc fecha y hora (UTC) de la última actualización de la fuente, de tipo {@code Instant}.\n     */\n    public record IndicadorEvento(String area, String nombre, String periodo, BigDecimal valor,\n                                  Instant fuenteActualizadaUtc) {\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/usuarios_accesos/infrastructure/outbox/OutboxEntity.java": "package com.mx.josesaid.develop.usuarios_accesos.infrastructure.outbox;\n\nimport jakarta.persistence.Column;\nimport jakarta.persistence.Entity;\nimport jakarta.persistence.Id;\nimport jakarta.persistence.Table;\nimport java.time.Instant;\nimport java.util.UUID;\n\n/** Evento pendiente de publicar a Kafka. Se escribe en la misma transacción que el cambio de negocio. */\n@Entity\n@Table(name = \"outbox_eventos\")\npublic class OutboxEntity {\n\n    @Id\n    private UUID id;\n\n    @Column(nullable = false, length = 100)\n    private String tipo;\n\n    @Column(name = \"agregado_id\", nullable = false, length = 100)\n    private String agregadoId;\n\n    /** Sobre JSON completo: tipo, agregadoId y datos. */\n    @Column(nullable = false, columnDefinition = \"TEXT\")\n    private String payload;\n\n    @Column(name = \"creado_utc\", nullable = false)\n    private Instant creadoUtc;\n\n    @Column(name = \"publicado_utc\")\n    private Instant publicadoUtc;\n\n    @Column(nullable = false)\n    private int intentos;\n\n    /** Constructor exigido por JPA. No se usa en el código de la aplicación. */\n    protected OutboxEntity() {\n        // requerido por JPA\n    }\n\n    /** Crea un evento pendiente de publicar en el outbox. */\n    public OutboxEntity(UUID id, String tipo, String agregadoId, String payload, Instant creadoUtc) {\n        this.id = id;\n        this.tipo = tipo;\n        this.agregadoId = agregadoId;\n        this.payload = payload;\n        this.creadoUtc = creadoUtc;\n        this.intentos = 0;\n    }\n\n    /** Marca el evento como publicado en la fecha indicada. */\n    public void marcarPublicado(Instant ahora) {\n        this.publicadoUtc = ahora;\n    }\n\n    /** Suma un intento fallido de publicación. */\n    public void registrarIntentoFallido() {\n        this.intentos++;\n    }\n\n    /** Devuelve el identificador del evento. */\n    public UUID getId() { return id; }\n    /** Devuelve el tipo del evento. */\n    public String getTipo() { return tipo; }\n    /** Devuelve el id del agregado al que pertenece el evento. */\n    public String getAgregadoId() { return agregadoId; }\n    /** Devuelve el contenido JSON del evento. */\n    public String getPayload() { return payload; }\n    /** Devuelve la fecha de creación en UTC. */\n    public Instant getCreadoUtc() { return creadoUtc; }\n    /** Devuelve la fecha de publicación en UTC, o nula si no se ha publicado. */\n    public Instant getPublicadoUtc() { return publicadoUtc; }\n    /** Devuelve el número de intentos fallidos. */\n    public int getIntentos() { return intentos; }\n}\n", "src/main/java/com/mx/josesaid/develop/usuarios_accesos/infrastructure/outbox/OutboxJpaRepository.java": "package com.mx.josesaid.develop.usuarios_accesos.infrastructure.outbox;\n\nimport java.util.List;\nimport java.util.UUID;\nimport org.springframework.data.jpa.repository.JpaRepository;\n\n/** Acceso a la tabla del outbox con Spring Data JPA. */\npublic interface OutboxJpaRepository extends JpaRepository<OutboxEntity, UUID> {\n\n    /** Eventos pendientes, del más antiguo al más nuevo, en lotes de 100. */\n    List<OutboxEntity> findTop100ByPublicadoUtcIsNullOrderByCreadoUtcAsc();\n}\n", "src/main/java/com/mx/josesaid/develop/usuarios_accesos/infrastructure/outbox/PublicadorEventosOutbox.java": "package com.mx.josesaid.develop.usuarios_accesos.infrastructure.outbox;\n\nimport com.mx.josesaid.develop.usuarios_accesos.application.EventoDominio;\nimport com.mx.josesaid.develop.usuarios_accesos.application.PublicadorEventos;\nimport java.time.Clock;\nimport java.time.Instant;\nimport java.util.Map;\nimport java.util.UUID;\nimport org.springframework.stereotype.Component;\nimport tools.jackson.databind.ObjectMapper;\n\n/**\n * Implementación del patrón outbox: guarda el evento en la base de datos dentro de la\n * transacción de negocio. El envío a Kafka lo hace {@link RetransmisorOutbox}.\n */\n@Component\npublic class PublicadorEventosOutbox implements PublicadorEventos {\n\n    private final OutboxJpaRepository outbox;\n    private final ObjectMapper mapper;\n    private final Clock reloj;\n\n    /** Recibe el repositorio del outbox, el serializador JSON y el reloj. */\n    public PublicadorEventosOutbox(OutboxJpaRepository outbox, ObjectMapper mapper, Clock reloj) {\n        this.outbox = outbox;\n        this.mapper = mapper;\n        this.reloj = reloj;\n    }\n\n    /** Guarda el evento en el outbox dentro de la misma transacción que el cambio de datos. */\n    @Override\n    public void publicar(EventoDominio evento) {\n        String sobre = mapper.writeValueAsString(Map.of(\n                \"tipo\", evento.tipo(),\n                \"agregadoId\", evento.agregadoId(),\n                \"datos\", evento.datos()));\n        outbox.save(new OutboxEntity(UUID.randomUUID(), evento.tipo(), evento.agregadoId(),\n                sobre, Instant.now(reloj)));\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/usuarios_accesos/infrastructure/outbox/RetransmisorOutbox.java": "package com.mx.josesaid.develop.usuarios_accesos.infrastructure.outbox;\n\nimport java.time.Clock;\nimport java.time.Instant;\nimport java.util.concurrent.TimeUnit;\nimport org.springframework.kafka.core.KafkaTemplate;\nimport org.springframework.scheduling.annotation.Scheduled;\nimport org.springframework.stereotype.Component;\nimport org.springframework.transaction.annotation.Transactional;\n\n/**\n * Envía a Kafka los eventos pendientes del outbox.\n *\n * <p>Se detiene en el primer fallo para conservar el orden de los eventos.\n * Un evento con error queda pendiente y se reintenta en el siguiente ciclo.\n */\n@Component\npublic class RetransmisorOutbox {\n\n    /** Tópico donde se publican los eventos de identidad. */\n    public static final String TOPICO = \"usuarios-accesos.eventos\";\n\n    private final OutboxJpaRepository outbox;\n    private final KafkaTemplate<String, String> kafka;\n    private final Clock reloj;\n\n    /** Recibe el repositorio del outbox, el productor de Kafka y el reloj. */\n    public RetransmisorOutbox(OutboxJpaRepository outbox, KafkaTemplate<String, String> kafka, Clock reloj) {\n        this.outbox = outbox;\n        this.kafka = kafka;\n        this.reloj = reloj;\n    }\n\n    /** Envía a Kafka los eventos pendientes. Si el envío falla, el evento queda para el siguiente intento. */\n    @Scheduled(fixedDelayString = \"${usuarios.outbox.intervalo-ms:5000}\")\n    @Transactional\n    public void transmitir() {\n        for (OutboxEntity evento : outbox.findTop100ByPublicadoUtcIsNullOrderByCreadoUtcAsc()) {\n            try {\n                kafka.send(TOPICO, evento.getAgregadoId(), evento.getPayload()).get(10, TimeUnit.SECONDS);\n                evento.marcarPublicado(Instant.now(reloj));\n            } catch (InterruptedException ie) {\n                Thread.currentThread().interrupt();\n                return;\n            } catch (Exception ex) {\n                evento.registrarIntentoFallido();\n                return;\n            }\n        }\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/usuarios_accesos/infrastructure/persistence/RefreshTokenEntity.java": "package com.mx.josesaid.develop.usuarios_accesos.infrastructure.persistence;\n\nimport jakarta.persistence.Column;\nimport jakarta.persistence.Entity;\nimport jakarta.persistence.Id;\nimport jakarta.persistence.Table;\nimport java.time.Instant;\nimport java.util.UUID;\n\n/** Fila de la tabla de refresh tokens. Guarda solo el hash del token, nunca el token. */\n@Entity\n@Table(name = \"refresh_tokens\")\npublic class RefreshTokenEntity {\n\n    @Id\n    private UUID id;\n\n    @Column(name = \"usuario_id\", nullable = false)\n    private UUID usuarioId;\n\n    @Column(name = \"familia_id\", nullable = false)\n    private UUID familiaId;\n\n    @Column(nullable = false, unique = true, length = 64)\n    private String hash;\n\n    @Column(name = \"creado_utc\", nullable = false)\n    private Instant creadoUtc;\n\n    @Column(name = \"expira_utc\", nullable = false)\n    private Instant expiraUtc;\n\n    @Column(name = \"usado_utc\")\n    private Instant usadoUtc;\n\n    @Column(name = \"revocado_utc\")\n    private Instant revocadoUtc;\n\n    /** Constructor exigido por JPA. No se usa en el código de la aplicación. */\n    protected RefreshTokenEntity() {\n        // requerido por JPA\n    }\n\n    /** Crea una fila de refresh token a partir de sus datos. */\n    public RefreshTokenEntity(UUID id, UUID usuarioId, UUID familiaId, String hash, Instant creadoUtc,\n                              Instant expiraUtc, Instant usadoUtc, Instant revocadoUtc) {\n        this.id = id;\n        this.usuarioId = usuarioId;\n        this.familiaId = familiaId;\n        this.hash = hash;\n        this.creadoUtc = creadoUtc;\n        this.expiraUtc = expiraUtc;\n        this.usadoUtc = usadoUtc;\n        this.revocadoUtc = revocadoUtc;\n    }\n\n    /** Devuelve el identificador. */\n    public UUID getId() { return id; }\n    /** Devuelve el id del usuario. */\n    public UUID getUsuarioId() { return usuarioId; }\n    /** Devuelve el id de la familia de sesión. */\n    public UUID getFamiliaId() { return familiaId; }\n    /** Devuelve el hash del token. */\n    public String getHash() { return hash; }\n    /** Devuelve la fecha de creación en UTC. */\n    public Instant getCreadoUtc() { return creadoUtc; }\n    /** Devuelve la fecha de expiración en UTC. */\n    public Instant getExpiraUtc() { return expiraUtc; }\n    /** Devuelve la fecha en que se usó, o nula si no se ha usado. */\n    public Instant getUsadoUtc() { return usadoUtc; }\n    /** Devuelve la fecha de revocación, o nula si sigue vigente. */\n    public Instant getRevocadoUtc() { return revocadoUtc; }\n}\n", "src/main/java/com/mx/josesaid/develop/usuarios_accesos/infrastructure/persistence/RefreshTokenJpaRepository.java": "package com.mx.josesaid.develop.usuarios_accesos.infrastructure.persistence;\n\nimport java.time.Instant;\nimport java.util.Optional;\nimport java.util.UUID;\nimport org.springframework.data.jpa.repository.JpaRepository;\nimport org.springframework.data.jpa.repository.Modifying;\nimport org.springframework.data.jpa.repository.Query;\nimport org.springframework.data.repository.query.Param;\n\n/** Acceso a la tabla de refresh tokens con Spring Data JPA. */\npublic interface RefreshTokenJpaRepository extends JpaRepository<RefreshTokenEntity, UUID> {\n\n    Optional<RefreshTokenEntity> findByHash(String hash);\n\n    @Modifying\n    @Query(\"update RefreshTokenEntity t set t.revocadoUtc = :ahora \"\n            + \"where t.familiaId = :familia and t.revocadoUtc is null\")\n    int revocarFamilia(@Param(\"familia\") UUID familia, @Param(\"ahora\") Instant ahora);\n\n    @Modifying\n    @Query(\"update RefreshTokenEntity t set t.revocadoUtc = :ahora \"\n            + \"where t.usuarioId = :usuario and t.revocadoUtc is null\")\n    int revocarTodasDeUsuario(@Param(\"usuario\") UUID usuario, @Param(\"ahora\") Instant ahora);\n}\n", "src/main/java/com/mx/josesaid/develop/usuarios_accesos/infrastructure/persistence/RefreshTokenRepositorioJpa.java": "package com.mx.josesaid.develop.usuarios_accesos.infrastructure.persistence;\n\nimport com.mx.josesaid.develop.usuarios_accesos.domain.RefreshToken;\nimport com.mx.josesaid.develop.usuarios_accesos.domain.RefreshTokenRepositorio;\nimport java.time.Instant;\nimport java.util.Optional;\nimport java.util.UUID;\nimport org.springframework.stereotype.Repository;\n\n/** Adaptador JPA del puerto de refresh tokens. */\n@Repository\npublic class RefreshTokenRepositorioJpa implements RefreshTokenRepositorio {\n\n    private final RefreshTokenJpaRepository jpa;\n\n    /** Recibe el repositorio JPA de refresh tokens. */\n    public RefreshTokenRepositorioJpa(RefreshTokenJpaRepository jpa) {\n        this.jpa = jpa;\n    }\n\n    /** Guarda o actualiza un refresh token. */\n    @Override\n    public void guardar(RefreshToken t) {\n        Instant creado = jpa.findById(t.id()).map(RefreshTokenEntity::getCreadoUtc).orElseGet(Instant::now);\n        jpa.save(new RefreshTokenEntity(t.id(), t.usuarioId(), t.familiaId(), t.hash(),\n                creado, t.expiraUtc(), t.usadoUtc(), t.revocadoUtc()));\n    }\n\n    /** Busca un refresh token por el hash de su valor. */\n    @Override\n    public Optional<RefreshToken> buscarPorHash(String hash) {\n        return jpa.findByHash(hash).map(e -> new RefreshToken(e.getId(), e.getUsuarioId(), e.getFamiliaId(),\n                e.getHash(), e.getExpiraUtc(), e.getUsadoUtc(), e.getRevocadoUtc()));\n    }\n\n    /** Revoca todos los tokens de una familia de sesión en la fecha indicada. */\n    @Override\n    public void revocarFamilia(UUID familiaId, Instant ahora) {\n        jpa.revocarFamilia(familiaId, ahora);\n    }\n\n    /** Revoca todas las sesiones de un usuario en la fecha indicada. */\n    @Override\n    public void revocarTodasDeUsuario(UUID usuarioId, Instant ahora) {\n        jpa.revocarTodasDeUsuario(usuarioId, ahora);\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/usuarios_accesos/infrastructure/persistence/UsuarioEntity.java": "package com.mx.josesaid.develop.usuarios_accesos.infrastructure.persistence;\n\nimport com.mx.josesaid.develop.usuarios_accesos.domain.EstatusUsuario;\nimport com.mx.josesaid.develop.usuarios_accesos.infrastructure.crypto.CampoCifradoConverter;\nimport com.mx.josesaid.develop.usuarios_accesos.domain.Rol;\nimport jakarta.persistence.CollectionTable;\nimport jakarta.persistence.Convert;\nimport jakarta.persistence.Column;\nimport jakarta.persistence.ElementCollection;\nimport jakarta.persistence.Entity;\nimport jakarta.persistence.EnumType;\nimport jakarta.persistence.Enumerated;\nimport jakarta.persistence.FetchType;\nimport jakarta.persistence.Id;\nimport jakarta.persistence.JoinColumn;\nimport jakarta.persistence.PrePersist;\nimport jakarta.persistence.PreUpdate;\nimport jakarta.persistence.Table;\nimport jakarta.persistence.Version;\nimport java.time.Instant;\nimport java.util.HashSet;\nimport java.util.Set;\nimport java.util.UUID;\n\n/** Modelo de persistencia de usuarios. Separado del agregado de dominio a propósito. */\n@Entity\n@Table(name = \"usuarios\")\npublic class UsuarioEntity {\n\n    @Id\n    private UUID id;\n\n    /** Cifrado AES-256-GCM. La unicidad la garantiza {@code correo_indice}. */\n    @Convert(converter = CampoCifradoConverter.class)\n    @Column(nullable = false, length = 400)\n    private String correo;\n\n    @Column(name = \"correo_indice\", length = 64)\n    private String correoIndice;\n\n    @Convert(converter = CampoCifradoConverter.class)\n    @Column(name = \"nombre_completo\", nullable = false, length = 400)\n    private String nombreCompleto;\n\n    @Column(name = \"password_hash\", nullable = false, length = 100)\n    private String passwordHash;\n\n    @Enumerated(EnumType.STRING)\n    @Column(nullable = false, length = 20)\n    private EstatusUsuario estatus;\n\n    @Column(name = \"intentos_fallidos\", nullable = false)\n    private int intentosFallidos;\n\n    @Column(name = \"bloqueado_hasta\")\n    private Instant bloqueadoHasta;\n\n    @Column(length = 40)\n    private String area;\n\n    @Column(name = \"debe_cambiar_password\", nullable = false)\n    private boolean debeCambiarPassword;\n\n    /** Control de concurrencia optimista. Lo gestiona JPA. */\n    @Version\n    private Long version;\n\n    @Column(name = \"creado_utc\", nullable = false, updatable = false)\n    private Instant creadoUtc;\n\n    @Column(name = \"actualizado_utc\", nullable = false)\n    private Instant actualizadoUtc;\n\n    @ElementCollection(fetch = FetchType.EAGER)\n    @CollectionTable(name = \"usuario_roles\", joinColumns = @JoinColumn(name = \"usuario_id\"))\n    @Enumerated(EnumType.STRING)\n    @Column(name = \"rol\", length = 30)\n    private Set<Rol> roles = new HashSet<>();\n\n    /** Constructor exigido por JPA. No se usa en el código de la aplicación. */\n    protected UsuarioEntity() {\n        // requerido por JPA\n    }\n\n    /** Se ejecuta antes de insertar la fila: fija la fecha de creación. */\n    @PrePersist\n    void alCrear() {\n        Instant ahora = Instant.now();\n        creadoUtc = ahora;\n        actualizadoUtc = ahora;\n    }\n\n    /** Se ejecuta antes de actualizar la fila: fija la fecha de modificación. */\n    @PreUpdate\n    void alActualizar() {\n        actualizadoUtc = Instant.now();\n    }\n\n    /** Devuelve el identificador. */\n    public UUID getId() { return id; }\n    /** Asigna el identificador. */\n    public void setId(UUID id) { this.id = id; }\n    /** Devuelve el correo tal como se guardó (cifrado). */\n    public String getCorreo() { return correo; }\n    /** Devuelve el índice de búsqueda del correo. */\n    public String getCorreoIndice() { return correoIndice; }\n    /** Asigna el índice de búsqueda del correo. */\n    public void setCorreoIndice(String correoIndice) { this.correoIndice = correoIndice; }\n    /** Asigna el correo, cifrado al guardarse. */\n    public void setCorreo(String correo) { this.correo = correo; }\n    /** Devuelve el nombre completo tal como se guardó (cifrado). */\n    public String getNombreCompleto() { return nombreCompleto; }\n    /** Asigna el nombre completo, cifrado al guardarse. */\n    public void setNombreCompleto(String nombreCompleto) { this.nombreCompleto = nombreCompleto; }\n    /** Devuelve el hash de la contraseña. */\n    public String getPasswordHash() { return passwordHash; }\n    /** Asigna el hash de la contraseña. */\n    public void setPasswordHash(String passwordHash) { this.passwordHash = passwordHash; }\n    /** Devuelve el estatus del usuario. */\n    public EstatusUsuario getEstatus() { return estatus; }\n    /** Asigna el estatus del usuario. */\n    public void setEstatus(EstatusUsuario estatus) { this.estatus = estatus; }\n    /** Devuelve los intentos fallidos consecutivos. */\n    public int getIntentosFallidos() { return intentosFallidos; }\n    /** Asigna los intentos fallidos consecutivos. */\n    public void setIntentosFallidos(int intentosFallidos) { this.intentosFallidos = intentosFallidos; }\n    /** Devuelve hasta cuándo está bloqueada la cuenta. */\n    public Instant getBloqueadoHasta() { return bloqueadoHasta; }\n    /** Asigna hasta cuándo está bloqueada la cuenta. */\n    public void setBloqueadoHasta(Instant bloqueadoHasta) { this.bloqueadoHasta = bloqueadoHasta; }\n    /** Devuelve el área del usuario. */\n    public String getArea() { return area; }\n    /** Asigna el área del usuario. */\n    public void setArea(String area) { this.area = area; }\n    /** Indica si la contraseña es temporal. */\n    public boolean isDebeCambiarPassword() { return debeCambiarPassword; }\n    /** Asigna el indicador de contraseña temporal. */\n    public void setDebeCambiarPassword(boolean valor) { this.debeCambiarPassword = valor; }\n    /** Devuelve la versión para control de concurrencia optimista. */\n    public Long getVersion() { return version; }\n    /** Devuelve los roles del usuario. */\n    public Set<Rol> getRoles() { return roles; }\n}\n", "src/main/java/com/mx/josesaid/develop/usuarios_accesos/infrastructure/persistence/UsuarioJpaRepository.java": "package com.mx.josesaid.develop.usuarios_accesos.infrastructure.persistence;\n\nimport java.util.Optional;\nimport java.util.UUID;\nimport org.springframework.data.jpa.repository.JpaRepository;\n\n/** Repositorio Spring Data. Solo lo usa el adaptador de persistencia. */\npublic interface UsuarioJpaRepository extends JpaRepository<UsuarioEntity, UUID> {\n\n    Optional<UsuarioEntity> findByCorreoIndice(String correoIndice);\n\n    boolean existsByCorreoIndice(String correoIndice);\n\n    java.util.List<UsuarioEntity> findAllByOrderByCreadoUtcDesc(org.springframework.data.domain.Pageable pageable);\n}\n", "src/main/java/com/mx/josesaid/develop/usuarios_accesos/infrastructure/persistence/UsuarioRepositorioJpa.java": "package com.mx.josesaid.develop.usuarios_accesos.infrastructure.persistence;\n\nimport com.mx.josesaid.develop.usuarios_accesos.infrastructure.crypto.IndiceCorreo;\n\nimport com.mx.josesaid.develop.usuarios_accesos.domain.Usuario;\nimport com.mx.josesaid.develop.usuarios_accesos.domain.UsuarioRepositorio;\nimport java.util.Optional;\nimport java.util.UUID;\nimport org.springframework.stereotype.Repository;\n\n/** Adaptador que implementa el puerto de dominio con JPA. */\n@Repository\npublic class UsuarioRepositorioJpa implements UsuarioRepositorio {\n\n    private final UsuarioJpaRepository jpa;\n\n    /** Recibe el repositorio JPA de usuarios. */\n    public UsuarioRepositorioJpa(UsuarioJpaRepository jpa) {\n        this.jpa = jpa;\n    }\n\n    /** Guarda un usuario y devuelve el guardado. */\n    @Override\n    public Usuario guardar(Usuario usuario) {\n        UsuarioEntity entidad = jpa.findById(usuario.getId()).orElseGet(UsuarioEntity::new);\n        entidad.setId(usuario.getId());\n        entidad.setCorreo(usuario.getCorreo());\n        entidad.setCorreoIndice(IndiceCorreo.de(usuario.getCorreo()));\n        entidad.setNombreCompleto(usuario.getNombreCompleto());\n        entidad.setPasswordHash(usuario.getPasswordHash());\n        entidad.setEstatus(usuario.getEstatus());\n        entidad.setIntentosFallidos(usuario.getIntentosFallidos());\n        entidad.setBloqueadoHasta(usuario.getBloqueadoHasta());\n        entidad.setArea(usuario.getArea());\n        entidad.setDebeCambiarPassword(usuario.debeCambiarPassword());\n        entidad.getRoles().clear();\n        entidad.getRoles().addAll(usuario.getRoles());\n        return toDominio(jpa.save(entidad));\n    }\n\n    /** Busca un usuario por id. */\n    @Override\n    public Optional<Usuario> buscarPorId(UUID id) {\n        return jpa.findById(id).map(UsuarioRepositorioJpa::toDominio);\n    }\n\n    /** Busca un usuario por correo normalizado, usando el índice de búsqueda. */\n    @Override\n    public Optional<Usuario> buscarPorCorreo(String correoNormalizado) {\n        return jpa.findByCorreoIndice(IndiceCorreo.de(correoNormalizado)).map(UsuarioRepositorioJpa::toDominio);\n    }\n\n    /** Indica si ya existe un usuario con ese correo normalizado. */\n    @Override\n    public boolean existePorCorreo(String correoNormalizado) {\n        return jpa.existsByCorreoIndice(IndiceCorreo.de(correoNormalizado));\n    }\n\n    /** Lista los usuarios más recientes, con límite. */\n    @Override\n    public java.util.List<Usuario> listarRecientes(int limite) {\n        return jpa.findAllByOrderByCreadoUtcDesc(org.springframework.data.domain.PageRequest.of(0, limite)).stream()\n                .map(UsuarioRepositorioJpa::toDominio)\n                .toList();\n    }\n\n    /** Convierte la fila en el usuario del dominio. */\n    private static Usuario toDominio(UsuarioEntity e) {\n        return Usuario.reconstruir(\n                e.getId(),\n                e.getCorreo(),\n                e.getNombreCompleto(),\n                e.getPasswordHash(),\n                e.getRoles(),\n                e.getEstatus(),\n                e.getIntentosFallidos(),\n                e.getBloqueadoHasta()).conArea(e.getArea()).conDebeCambiarPassword(e.isDebeCambiarPassword());\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/usuarios_accesos/infrastructure/security/EmisorTokens.java": "package com.mx.josesaid.develop.usuarios_accesos.infrastructure.security;\n\nimport java.util.UUID;\n\nimport com.mx.josesaid.develop.usuarios_accesos.config.PropiedadesJwt;\nimport com.mx.josesaid.develop.usuarios_accesos.domain.Usuario;\nimport java.time.Clock;\nimport java.time.Instant;\nimport com.mx.josesaid.develop.usuarios_accesos.config.ClavesJwt;\nimport org.springframework.security.oauth2.jose.jws.SignatureAlgorithm;\nimport org.springframework.security.oauth2.jwt.JwsHeader;\nimport org.springframework.security.oauth2.jwt.JwtClaimsSet;\nimport org.springframework.security.oauth2.jwt.JwtEncoder;\nimport org.springframework.security.oauth2.jwt.JwtEncoderParameters;\nimport org.springframework.stereotype.Component;\n\n/** Emite tokens de acceso firmados con RS256. El claim {@code roles} alimenta la autorización. */\n@Component\npublic class EmisorTokens {\n\n    private final JwtEncoder encoder;\n    private final PropiedadesJwt propiedades;\n    private final Clock reloj;\n\n    /** Recibe el codificador JWT, las propiedades y el reloj. */\n    public EmisorTokens(JwtEncoder encoder, PropiedadesJwt propiedades, Clock reloj) {\n        this.encoder = encoder;\n        this.propiedades = propiedades;\n        this.reloj = reloj;\n    }\n\n    /** Emite un access token RS256 con el id del usuario como sujeto, sus roles, su área y el id de sesión (sid). */\n    public String emitir(Usuario usuario, UUID sesion) {\n        Instant ahora = Instant.now(reloj);\n        JwtClaimsSet.Builder reclamaciones = JwtClaimsSet.builder()\n                .issuer(propiedades.emisor())\n                .subject(usuario.getId().toString())\n                .issuedAt(ahora)\n                .expiresAt(ahora.plus(propiedades.duracion()))\n                .claim(\"roles\", usuario.getRoles().stream().map(Enum::name).toList())\n                .claim(\"sid\", sesion.toString());\n        if (usuario.getCorreo() != null) {\n            reclamaciones.claim(\"correo\", usuario.getCorreo());\n        }\n        if (usuario.getArea() != null) {\n            reclamaciones.claim(\"area\", usuario.getArea());\n        }\n        JwtClaimsSet claims = reclamaciones.build();\n        JwsHeader cabecera = JwsHeader.with(SignatureAlgorithm.RS256).keyId(ClavesJwt.kid(propiedades.kid())).build();\n        return encoder.encode(JwtEncoderParameters.from(cabecera, claims)).getTokenValue();\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/usuarios_accesos/seguridad/EntradaNoAutorizada.java": "package com.mx.josesaid.develop.usuarios_accesos.seguridad;\n\nimport jakarta.servlet.http.HttpServletRequest;\nimport jakarta.servlet.http.HttpServletResponse;\nimport java.io.IOException;\nimport org.springframework.security.core.AuthenticationException;\nimport org.springframework.security.oauth2.jwt.JwtValidationException;\nimport org.springframework.security.web.AuthenticationEntryPoint;\n\n/**\n * Responde 401 y deja el motivo en WWW-Authenticate. Solo expone el motivo de sesión cerrada;\n * cualquier otro fallo de validación se reporta como \"Invalid token\", sin detalles de decodificación.\n * Spring puede llamar dos veces al punto de entrada en la misma petición: el primer motivo se conserva.\n */\npublic class EntradaNoAutorizada implements AuthenticationEntryPoint {\n\n    private static final String MOTIVO_GENERICO = \"Invalid token\";\n    private static final String ATRIBUTO = EntradaNoAutorizada.class.getName() + \".motivo\";\n\n    /** Responde 401 cuando la petición no trae un token válido o el token fue rechazado. */\n    @Override\n    public void commence(HttpServletRequest request, HttpServletResponse response, AuthenticationException ex)\n            throws IOException {\n        String previo = (String) request.getAttribute(ATRIBUTO);\n        String motivo = previo != null ? previo : motivo(ex);\n        request.setAttribute(ATRIBUTO, motivo);\n        response.setHeader(\"WWW-Authenticate\",\n                \"Bearer error=\\\"invalid_token\\\", error_description=\\\"\" + motivo + \"\\\"\");\n        response.sendError(HttpServletResponse.SC_UNAUTHORIZED);\n    }\n\n    /** Explica por qué se rechazó el token, en texto breve para el log. */\n    private static String motivo(Throwable ex) {\n        for (Throwable t = ex; t != null; t = t.getCause()) {\n            if (t instanceof JwtValidationException jve && jve.getErrors().stream()\n                    .anyMatch(e -> ValidadorRevocacion.MOTIVO.equals(e.getDescription()))) {\n                return ValidadorRevocacion.MOTIVO;\n            }\n        }\n        return MOTIVO_GENERICO;\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/usuarios_accesos/seguridad/ListenerRevocaciones.java": "package com.mx.josesaid.develop.usuarios_accesos.seguridad;\n\nimport java.time.Instant;\nimport java.util.Map;\nimport org.slf4j.Logger;\nimport org.slf4j.LoggerFactory;\nimport org.springframework.kafka.annotation.KafkaListener;\nimport org.springframework.stereotype.Component;\nimport tools.jackson.databind.ObjectMapper;\n\n/**\n * Recibe de usuarios-accesos-ms los cierres de sesión y los aplica a la copia local de revocaciones.\n * Los eventos ajenos se ignoran; un mensaje inválido se registra y se descarta.\n * Cada arranque usa un grupo de consumo nuevo y lee el topic desde el inicio: así reconstruye las\n * revocaciones vigentes. Los eventos vencidos los descarta RevocacionSesiones.\n */\n@Component\npublic class ListenerRevocaciones {\n\n    private static final Logger log = LoggerFactory.getLogger(ListenerRevocaciones.class);\n\n    private final RevocacionSesiones revocaciones;\n    private final ObjectMapper mapper;\n\n    /** Recibe la copia local de revocaciones y el lector JSON. */\n    public ListenerRevocaciones(RevocacionSesiones revocaciones, ObjectMapper mapper) {\n        this.revocaciones = revocaciones;\n        this.mapper = mapper;\n    }\n\n    /** Aplica al instante un evento de cierre de sesión recibido por Kafka. */\n    @KafkaListener(topics = \"${seguridad.revocaciones.topico:usuarios-accesos.eventos}\",\n                   groupId = \"usuarios-accesos-ms-revocaciones-#{T(java.util.UUID).randomUUID()}\",\n                   properties = \"auto.offset.reset=earliest\")\n    public void recibir(String mensaje) {\n        try {\n            Sobre sobre = mapper.readValue(mensaje, Sobre.class);\n            String tipo = sobre.tipo();\n            if (!\"sesion-cerrada\".equals(tipo) && !\"sesiones-usuario-cerradas\".equals(tipo)) {\n                return;\n            }\n            Map<String, Object> datos = sobre.datos() == null ? Map.of() : sobre.datos();\n            Instant ocurridoEn = Instant.parse(String.valueOf(datos.get(\"ocurridoEn\")));\n            if (\"sesion-cerrada\".equals(tipo)) {\n                revocaciones.revocarSesion(String.valueOf(datos.get(\"sid\")), ocurridoEn);\n            } else {\n                revocaciones.revocarUsuario(String.valueOf(datos.get(\"usuarioId\")), ocurridoEn);\n            }\n        } catch (RuntimeException e) {\n            log.warn(\"Evento de revocación descartado: {}\", e.getClass().getSimpleName());\n        }\n    }\n\n    /**\n     * Sobre que publica usuarios-accesos-ms por el outbox.\n     *\n     * @param tipo tipo o clasificación del registro, de tipo {@code String}.\n     * @param agregadoId identificador del agregado de dominio al que pertenece el evento, de tipo {@code String}.\n     * @param datos datos específicos de la operación, de tipo {@code Map<String, Object>}.\n     */\n    public record Sobre(String tipo, String agregadoId, Map<String, Object> datos) {\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/usuarios_accesos/seguridad/RevocacionSesiones.java": "package com.mx.josesaid.develop.usuarios_accesos.seguridad;\n\nimport java.time.Duration;\nimport java.time.Instant;\nimport java.util.Map;\nimport java.util.concurrent.ConcurrentHashMap;\nimport org.springframework.stereotype.Component;\n\n/**\n * Sesiones cerradas, recordadas en memoria solo mientras pueda haber tokens vigentes.\n * Cada servicio mantiene su copia: un reinicio la vacía, y los tokens revocados expiran igual en 15 minutos.\n */\n@Component\npublic class RevocacionSesiones {\n\n    /** Vida del access token (15 min) más un margen. Pasado ese tiempo, ningún token revocado sigue vigente. */\n    public static final Duration VIDA = Duration.ofMinutes(20);\n\n    private final Map<String, Instant> sesiones = new ConcurrentHashMap<>();\n    private final Map<String, Instant> usuarios = new ConcurrentHashMap<>();\n\n    /** Revoca una sesión (su sid) cerrada en el instante dado. */\n    public void revocarSesion(String sid, Instant ocurridoEn) {\n        if (sid == null || vencido(ocurridoEn)) {\n            return;\n        }\n        sesiones.put(sid, ocurridoEn);\n    }\n\n    /** Revoca los tokens del usuario emitidos antes del instante dado. */\n    public void revocarUsuario(String usuarioId, Instant ocurridoEn) {\n        if (usuarioId == null || vencido(ocurridoEn)) {\n            return;\n        }\n        usuarios.merge(usuarioId, ocurridoEn, (actual, nuevoValor) -> nuevoValor.isAfter(actual) ? nuevoValor : actual);\n    }\n\n    /** true si un token con ese sid, usuario y fecha de emisión ya no debe aceptarse. */\n    public boolean revocado(String sid, String usuarioId, Instant emitidoEn) {\n        limpiar();\n        if (sid != null && sesiones.containsKey(sid)) {\n            return true;\n        }\n        Instant cerradoEn = usuarioId == null ? null : usuarios.get(usuarioId);\n        return cerradoEn != null && emitidoEn != null && emitidoEn.isBefore(cerradoEn);\n    }\n\n    /** Indica si un registro de revocación ya venció y puede descartarse. */\n    private static boolean vencido(Instant ocurridoEn) {\n        return ocurridoEn == null || ocurridoEn.plus(VIDA).isBefore(Instant.now());\n    }\n\n    /** Elimina las revocaciones vencidas para no crecer sin límite. */\n    private void limpiar() {\n        Instant limite = Instant.now().minus(VIDA);\n        sesiones.values().removeIf(t -> t.isBefore(limite));\n        usuarios.values().removeIf(t -> t.isBefore(limite));\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/usuarios_accesos/seguridad/ValidadorRevocacion.java": "package com.mx.josesaid.develop.usuarios_accesos.seguridad;\n\nimport org.springframework.security.oauth2.core.OAuth2Error;\nimport org.springframework.security.oauth2.core.OAuth2TokenValidator;\nimport org.springframework.security.oauth2.core.OAuth2TokenValidatorResult;\nimport org.springframework.security.oauth2.jwt.Jwt;\n\n/** Rechaza los tokens de sesiones cerradas. Se combina con la validación estándar de firma y vencimiento. */\npublic class ValidadorRevocacion implements OAuth2TokenValidator<Jwt> {\n\n    /** Motivo que se devuelve al cliente cuando la sesión fue cerrada. */\n    public static final String MOTIVO = \"La sesion fue cerrada\";\n\n    private static final OAuth2Error REVOCADO = new OAuth2Error(\"invalid_token\", MOTIVO, null);\n\n    private final RevocacionSesiones revocaciones;\n\n    /** Recibe la copia local de revocaciones. */\n    public ValidadorRevocacion(RevocacionSesiones revocaciones) {\n        this.revocaciones = revocaciones;\n    }\n\n    /** Rechaza el JWT si su sesión o su usuario fueron revocados, aunque la firma y el vencimiento sean válidos. */\n    @Override\n    public OAuth2TokenValidatorResult validate(Jwt jwt) {\n        boolean revocado = revocaciones.revocado(jwt.getClaimAsString(\"sid\"), jwt.getSubject(), jwt.getIssuedAt());\n        return revocado ? OAuth2TokenValidatorResult.failure(REVOCADO) : OAuth2TokenValidatorResult.success();\n    }\n}\n", "src/test/java/com/mx/josesaid/develop/usuarios_accesos/api/UsuarioControllerAutorizacionTest.java": "package com.mx.josesaid.develop.usuarios_accesos.api;\n\nimport static org.springframework.security.test.web.servlet.request.SecurityMockMvcRequestPostProcessors.jwt;\nimport static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;\nimport static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;\n\nimport com.mx.josesaid.develop.usuarios_accesos.application.UsuarioService;\nimport com.mx.josesaid.develop.usuarios_accesos.config.PropiedadesJwt;\nimport com.mx.josesaid.develop.usuarios_accesos.config.SeguridadConfig;\nimport com.nimbusds.jose.jwk.JWKSet;\nimport com.nimbusds.jose.jwk.RSAKey;\nimport org.springframework.security.oauth2.jwt.JwtEncoder;\nimport java.util.List;\nimport org.assertj.core.api.Assertions;\nimport org.junit.jupiter.api.Test;\nimport org.springframework.beans.factory.annotation.Autowired;\nimport org.springframework.boot.test.context.TestConfiguration;\nimport org.springframework.boot.webmvc.test.autoconfigure.WebMvcTest;\nimport org.springframework.context.annotation.Import;\nimport org.springframework.security.config.annotation.web.configuration.EnableWebSecurity;\nimport org.springframework.security.core.GrantedAuthority;\nimport org.springframework.security.core.authority.SimpleGrantedAuthority;\nimport org.springframework.security.oauth2.jwt.JwtDecoder;\nimport org.springframework.test.context.bean.override.mockito.MockitoBean;\nimport org.springframework.test.web.servlet.MockMvc;\nimport org.springframework.test.web.servlet.request.MockHttpServletRequestBuilder;\n\n/**\n * Matriz de autorización de UsuarioController: todo /v1/usuarios exige ROLE_ADMIN.\n */\n@WebMvcTest(UsuarioController.class)\n@Import({SeguridadConfig.class, UsuarioControllerAutorizacionTest.Configuracion.class})\nclass UsuarioControllerAutorizacionTest {\n\n    private static final String SUJETO = \"6f1c2e7a-9a3b-4c1d-8e2f-1a2b3c4d5e6f\";\n\n    @TestConfiguration\n    @EnableWebSecurity\n    static class Configuracion {\n    }\n\n    @Autowired\n    private MockMvc mvc;\n\n    @MockitoBean\n    private UsuarioService servicio;\n\n    @MockitoBean\n    private JwtDecoder jwtDecoder;\n\n    // Beans de claves: se simulan para no cargar material criptográfico en esta prueba de autorización.\n    @MockitoBean\n    private PropiedadesJwt propiedadesJwt;\n\n    @MockitoBean\n    private RSAKey claveRsa;\n\n    @MockitoBean\n    private JWKSet clavesPublicas;\n\n    @MockitoBean\n    private JwtEncoder jwtEncoder;\n\n    private MockHttpServletRequestBuilder peticion(MockHttpServletRequestBuilder base, String rol) {\n        List<GrantedAuthority> autoridades = rol.isEmpty() ? List.of()\n                : List.of(new SimpleGrantedAuthority(\"ROLE_\" + rol));\n        return base.with(org.springframework.security.test.web.servlet.request.SecurityMockMvcRequestPostProcessors\n                .jwt().jwt(j -> j.subject(SUJETO)).authorities(autoridades));\n    }\n\n    private void permitido(MockHttpServletRequestBuilder req, String descripcion, String rol) throws Exception {\n        int codigo;\n        try {\n            codigo = mvc.perform(req).andReturn().getResponse().getStatus();\n        } catch (jakarta.servlet.ServletException e) {\n            codigo = 200; // llegó al controlador: el rol fue aceptado\n        }\n        Assertions.assertThat(codigo)\n                .as(\"%s debería estar permitido para %s\", descripcion, rol)\n                .isNotIn(401, 403);\n    }\n\n    @Test\n    void usuariosSoloParaAdmin() throws Exception {\n        String ruta = \"/v1/usuarios\";\n        permitido(peticion(get(ruta), \"ADMIN\"), \"GET usuarios\", \"ADMIN\");\n        mvc.perform(peticion(get(ruta), \"VENTAS\")).andExpect(status().isForbidden());\n        mvc.perform(peticion(get(ruta), \"CONTADOR\")).andExpect(status().isForbidden());\n        mvc.perform(peticion(get(ruta), \"\")).andExpect(status().isForbidden());\n    }\n}\n", "src/test/java/com/mx/josesaid/develop/usuarios_accesos/api/UsuariosAccesosIT.java": "package com.mx.josesaid.develop.usuarios_accesos.api;\n\nimport static org.hamcrest.Matchers.notNullValue;\nimport static org.junit.jupiter.api.Assertions.assertNotEquals;\nimport static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;\nimport static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;\nimport static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;\nimport static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;\n\nimport com.mx.josesaid.develop.usuarios_accesos.application.UsuarioService;\nimport com.mx.josesaid.develop.usuarios_accesos.domain.Rol;\nimport java.security.KeyPairGenerator;\nimport java.util.Base64;\nimport java.util.Set;\nimport org.junit.jupiter.api.Test;\nimport org.springframework.beans.factory.annotation.Autowired;\nimport org.springframework.http.MediaType;\nimport org.springframework.boot.webmvc.test.autoconfigure.AutoConfigureMockMvc;\nimport org.springframework.boot.test.context.SpringBootTest;\nimport org.springframework.boot.testcontainers.service.connection.ServiceConnection;\nimport org.springframework.test.context.DynamicPropertyRegistry;\nimport org.springframework.test.context.DynamicPropertySource;\nimport org.springframework.test.web.servlet.MockMvc;\nimport org.testcontainers.kafka.KafkaContainer;\nimport org.testcontainers.postgresql.PostgreSQLContainer;\nimport org.testcontainers.junit.jupiter.Container;\nimport org.testcontainers.junit.jupiter.Testcontainers;\n\n/**\n * Prueba de integración con PostgreSQL y Kafka reales (Testcontainers).\n * Requiere Docker. Se ejecuta con 'mvn verify'.\n */\n@SpringBootTest\n@AutoConfigureMockMvc\n@Testcontainers\nclass UsuariosAccesosIT {\n\n    /** Correo único por ejecución: no choca con administradores de otras corridas o del entorno. */\n    private static final String CORREO_ADMIN = \"admin-\" + java.util.UUID.randomUUID() + \"@prueba.mx\";\n\n    @Container\n    @ServiceConnection\n    static PostgreSQLContainer postgres = new PostgreSQLContainer(\"postgres:17-alpine\");\n\n    @Container\n    @ServiceConnection\n    static KafkaContainer kafka = new KafkaContainer(\"apache/kafka:4.0.0\");\n\n    @Autowired\n    private MockMvc mvc;\n\n    @Autowired\n    private UsuarioService servicio;\n\n    /** Genera una clave RSA de prueba en cada ejecución; no se guarda en el repositorio. */\n    @DynamicPropertySource\n    static void claveJwtDePrueba(DynamicPropertyRegistry registro) throws Exception {\n        KeyPairGenerator generador = KeyPairGenerator.getInstance(\"RSA\");\n        generador.initialize(2048);\n        String pkcs8 = Base64.getEncoder().encodeToString(generador.generateKeyPair().getPrivate().getEncoded());\n        registro.add(\"usuarios.jwt.clave-privada\", () -> pkcs8);\n        registro.add(\"USUARIOS_CIFRADO_CLAVE\", () -> Base64.getEncoder()\n                .encodeToString(\"0123456789abcdef0123456789abcdef\".getBytes()));\n        registro.add(\"USUARIOS_INDICE_CLAVE\", () -> Base64.getEncoder()\n                .encodeToString(\"fedcba9876543210fedcba9876543210\".getBytes()));\n    }\n\n    @Test\n    void loginEmiteTokenYLaRutaProtegidaRechazaSinToken() throws Exception {\n        servicio.crear(CORREO_ADMIN, \"Administrador General\", \"clave-admin-123\", Set.of(Rol.ADMIN));\n\n        mvc.perform(post(\"/v1/auth/login\")\n                        .contentType(\"application/json\")\n                        .content(\"{\\\"correo\\\":\\\"\" + CORREO_ADMIN + \"\\\",\\\"password\\\":\\\"clave-admin-123\\\"}\"))\n                .andExpect(status().isOk())\n                .andExpect(jsonPath(\"$.accessToken\").value(notNullValue()))\n                .andExpect(jsonPath(\"$.tokenType\").value(\"Bearer\"));\n\n        mvc.perform(get(\"/v1/usuarios/00000000-0000-0000-0000-000000000000\"))\n                .andExpect(status().isUnauthorized());\n    }\n\n    @Test\n    void refrescoRotaYElReusoRevocaLaSesion() throws Exception {\n        String correo = \"sesion-\" + java.util.UUID.randomUUID() + \"@prueba.mx\";\n        servicio.crear(correo, \"Usuario de Sesión\", \"clave-sesion-123\", Set.of(Rol.VENTAS));\n        String r1 = campo(iniciarSesion(correo), \"refreshToken\");\n\n        String refrescado = mvc.perform(post(\"/v1/auth/refresh\").contentType(\"application/json\")\n                        .content(\"{\\\"refreshToken\\\":\\\"\" + r1 + \"\\\"}\"))\n                .andExpect(status().isOk())\n                .andReturn().getResponse().getContentAsString();\n        String r2 = campo(refrescado, \"refreshToken\");\n        assertNotEquals(r1, r2);\n\n        // Reusar el token ya rotado revoca la sesión completa, incluido el token nuevo\n        mvc.perform(post(\"/v1/auth/refresh\").contentType(\"application/json\")\n                        .content(\"{\\\"refreshToken\\\":\\\"\" + r1 + \"\\\"}\"))\n                .andExpect(status().isUnauthorized());\n        mvc.perform(post(\"/v1/auth/refresh\").contentType(\"application/json\")\n                        .content(\"{\\\"refreshToken\\\":\\\"\" + r2 + \"\\\"}\"))\n                .andExpect(status().isUnauthorized());\n    }\n\n    @Test\n    void logoutCierraLaSesionYLogoutTodasCierraTodas() throws Exception {\n        String correo = \"logout-\" + java.util.UUID.randomUUID() + \"@prueba.mx\";\n        servicio.crear(correo, \"Usuario de Logout\", \"clave-logout-123\", Set.of(Rol.VENTAS));\n        String sesion1 = iniciarSesion(correo);\n        String r1 = campo(sesion1, \"refreshToken\");\n\n        mvc.perform(post(\"/v1/auth/logout\").contentType(\"application/json\")\n                        .content(\"{\\\"refreshToken\\\":\\\"\" + r1 + \"\\\"}\"))\n                .andExpect(status().isNoContent());\n        mvc.perform(post(\"/v1/auth/refresh\").contentType(\"application/json\")\n                        .content(\"{\\\"refreshToken\\\":\\\"\" + r1 + \"\\\"}\"))\n                .andExpect(status().isUnauthorized());\n\n        String sesion2 = iniciarSesion(correo);\n        String r2 = campo(sesion2, \"refreshToken\");\n        String acceso = campo(sesion2, \"accessToken\");\n        mvc.perform(post(\"/v1/auth/logout-todas\").header(\"Authorization\", \"Bearer \" + acceso))\n                .andExpect(status().isNoContent());\n        mvc.perform(post(\"/v1/auth/refresh\").contentType(\"application/json\")\n                        .content(\"{\\\"refreshToken\\\":\\\"\" + r2 + \"\\\"}\"))\n                .andExpect(status().isUnauthorized());\n    }\n\n    @Test\n    void passwordTemporalBloqueaElLoginHastaCambiarla() throws Exception {\n        String correo = \"temporal-\" + java.util.UUID.randomUUID() + \"@prueba.mx\";\n        String temporal = \"Temporal-inicial-123\";\n        String nueva = \"Nueva-clave-segura-456\";\n        servicio.crearConPasswordTemporal(correo, \"Usuario Temporal\", temporal, Set.of(Rol.VENTAS));\n\n        mvc.perform(post(\"/v1/auth/login\").contentType(MediaType.APPLICATION_JSON)\n                        .content(\"{\\\"correo\\\":\\\"\" + correo + \"\\\",\\\"password\\\":\\\"\" + temporal + \"\\\"}\"))\n                .andExpect(status().isForbidden());\n\n        mvc.perform(post(\"/v1/auth/cambiar-password-inicial\").contentType(MediaType.APPLICATION_JSON)\n                        .content(\"{\\\"correo\\\":\\\"\" + correo + \"\\\",\\\"passwordActual\\\":\\\"\" + temporal\n                                + \"\\\",\\\"passwordNueva\\\":\\\"\" + nueva + \"\\\"}\"))\n                .andExpect(status().isNoContent());\n\n        mvc.perform(post(\"/v1/auth/login\").contentType(MediaType.APPLICATION_JSON)\n                        .content(\"{\\\"correo\\\":\\\"\" + correo + \"\\\",\\\"password\\\":\\\"\" + nueva + \"\\\"}\"))\n                .andExpect(status().isOk());\n    }\n\n    private String iniciarSesion(String correo) throws Exception {\n        return mvc.perform(post(\"/v1/auth/login\").contentType(\"application/json\")\n                        .content(\"{\\\"correo\\\":\\\"\" + correo + \"\\\",\\\"password\\\":\\\"\" + clave(correo) + \"\\\"}\"))\n                .andExpect(status().isOk())\n                .andReturn().getResponse().getContentAsString();\n    }\n\n    private static String clave(String correo) {\n        return correo.startsWith(\"logout-\") ? \"clave-logout-123\" : \"clave-sesion-123\";\n    }\n\n    private static String campo(String json, String nombre) {\n        java.util.regex.Matcher m = java.util.regex.Pattern\n                .compile(\"\\\"\" + nombre + \"\\\":\\\"([^\\\"]+)\\\"\").matcher(json);\n        if (!m.find()) {\n            throw new IllegalStateException(\"No se encontró \" + nombre);\n        }\n        return m.group(1);\n    }\n}\n", "src/test/java/com/mx/josesaid/develop/usuarios_accesos/application/SesionServiceTest.java": "package com.mx.josesaid.develop.usuarios_accesos.application;\n\nimport static org.assertj.core.api.Assertions.assertThat;\nimport static org.assertj.core.api.Assertions.assertThatThrownBy;\nimport static org.mockito.ArgumentMatchers.any;\nimport static org.mockito.ArgumentMatchers.anyString;\nimport static org.mockito.ArgumentMatchers.argThat;\nimport static org.mockito.ArgumentMatchers.eq;\nimport static org.mockito.Mockito.mock;\nimport static org.mockito.Mockito.never;\nimport static org.mockito.Mockito.verify;\nimport static org.mockito.Mockito.when;\n\nimport com.mx.josesaid.develop.usuarios_accesos.domain.CredencialesInvalidasException;\nimport com.mx.josesaid.develop.usuarios_accesos.domain.RefreshToken;\nimport com.mx.josesaid.develop.usuarios_accesos.domain.RefreshTokenRepositorio;\nimport com.mx.josesaid.develop.usuarios_accesos.domain.Rol;\nimport com.mx.josesaid.develop.usuarios_accesos.domain.Usuario;\nimport com.mx.josesaid.develop.usuarios_accesos.domain.UsuarioRepositorio;\nimport com.mx.josesaid.develop.usuarios_accesos.infrastructure.security.EmisorTokens;\nimport java.time.Clock;\nimport java.time.Instant;\nimport java.time.ZoneOffset;\nimport java.util.List;\nimport java.util.Optional;\nimport java.util.UUID;\nimport org.junit.jupiter.api.Test;\n\nclass SesionServiceTest {\n\n    private static final Instant AHORA = Instant.parse(\"2026-10-29T15:00:00Z\");\n\n    private final RefreshTokenRepositorio refrescos = mock(RefreshTokenRepositorio.class);\n    private final UsuarioRepositorio usuarios = mock(UsuarioRepositorio.class);\n    private final EmisorTokens emisor = mock(EmisorTokens.class);\n    private final PublicadorEventos publicador = mock(PublicadorEventos.class);\n    private final SesionService sesiones = new SesionService(refrescos, usuarios, emisor,\n            Clock.fixed(AHORA, ZoneOffset.UTC), publicador);\n    private final Usuario ana = Usuario.crear(\"ana@empresa.mx\", \"Ana Ruiz\", \"hash\", List.of(Rol.VENTAS));\n\n    @Test\n    void iniciarEmiteAccesoYRefrescoNuevo() {\n        when(emisor.emitir(eq(ana), any())).thenReturn(\"acceso\");\n        SesionService.Par par = sesiones.iniciar(ana);\n        assertThat(par.accessToken()).isEqualTo(\"acceso\");\n        assertThat(par.refreshToken()).isNotBlank();\n        verify(refrescos).guardar(any(RefreshToken.class));\n    }\n\n    @Test\n    void refrescarRotaElTokenYConservaLaFamilia() {\n        UUID familia = UUID.randomUUID();\n        RefreshToken actual = new RefreshToken(UUID.randomUUID(), ana.getId(), familia, \"h\",\n                AHORA.plusSeconds(3600), null, null);\n        when(refrescos.buscarPorHash(anyString())).thenReturn(Optional.of(actual));\n        when(usuarios.buscarPorId(ana.getId())).thenReturn(Optional.of(ana));\n        when(emisor.emitir(eq(ana), any())).thenReturn(\"acceso\");\n\n        sesiones.refrescar(\"plano\");\n\n        verify(refrescos).guardar(argThat((RefreshToken r) -> r.id().equals(actual.id()) && r.usadoUtc() != null));\n        verify(refrescos).guardar(argThat((RefreshToken r) ->\n                r.familiaId().equals(familia) && r.usadoUtc() == null));\n    }\n\n    @Test\n    void reusoDeTokenRotadoRevocaLaFamiliaYRechaza() {\n        UUID familia = UUID.randomUUID();\n        RefreshToken usado = new RefreshToken(UUID.randomUUID(), ana.getId(), familia, \"h\",\n                AHORA.plusSeconds(3600), AHORA.minusSeconds(60), null);\n        when(refrescos.buscarPorHash(anyString())).thenReturn(Optional.of(usado));\n\n        assertThatThrownBy(() -> sesiones.refrescar(\"plano\")).isInstanceOf(CredencialesInvalidasException.class);\n        verify(refrescos).revocarFamilia(familia, AHORA);\n        verify(emisor, never()).emitir(any(), any());\n    }\n\n    @Test\n    void tokenVencidoSeRechaza() {\n        RefreshToken vencido = new RefreshToken(UUID.randomUUID(), ana.getId(), UUID.randomUUID(), \"h\",\n                AHORA.minusSeconds(1), null, null);\n        when(refrescos.buscarPorHash(anyString())).thenReturn(Optional.of(vencido));\n\n        assertThatThrownBy(() -> sesiones.refrescar(\"plano\")).isInstanceOf(CredencialesInvalidasException.class);\n        verify(emisor, never()).emitir(any(), any());\n    }\n\n    @Test\n    void cerrarRevocaLaFamiliaDelToken() {\n        UUID familia = UUID.randomUUID();\n        RefreshToken t = new RefreshToken(UUID.randomUUID(), ana.getId(), familia, \"h\",\n                AHORA.plusSeconds(3600), null, null);\n        when(refrescos.buscarPorHash(anyString())).thenReturn(Optional.of(t));\n\n        sesiones.cerrar(\"plano\");\n\n        verify(refrescos).revocarFamilia(familia, AHORA);\n    }\n\n    @Test\n    void cerrarTodasRevocaTodasLasSesionesDelUsuario() {\n        sesiones.cerrarTodas(ana.getId());\n        verify(refrescos).revocarTodasDeUsuario(ana.getId(), AHORA);\n    }\n\n    @Test\n    void cerrarPublicaElEventoDeSesionCerrada() {\n        UUID familia = UUID.randomUUID();\n        RefreshToken t = new RefreshToken(UUID.randomUUID(), ana.getId(), familia, \"h\",\n                AHORA.plusSeconds(3600), null, null);\n        when(refrescos.buscarPorHash(anyString())).thenReturn(Optional.of(t));\n\n        sesiones.cerrar(\"plano\");\n\n        verify(publicador).publicar(argThat((EventoDominio e) ->\n                e.tipo().equals(\"sesion-cerrada\") && familia.toString().equals(e.datos().get(\"sid\"))));\n    }\n\n    @Test\n    void cerrarTodasPublicaElEventoDeSesionesDelUsuario() {\n        sesiones.cerrarTodas(ana.getId());\n        verify(publicador).publicar(argThat((EventoDominio e) ->\n                e.tipo().equals(\"sesiones-usuario-cerradas\") && ana.getId().toString().equals(e.datos().get(\"usuarioId\"))));\n    }\n}\n", "src/test/java/com/mx/josesaid/develop/usuarios_accesos/application/UsuarioListarRecientesTest.java": "package com.mx.josesaid.develop.usuarios_accesos.application;\n\nimport static org.assertj.core.api.Assertions.assertThat;\nimport static org.mockito.ArgumentMatchers.eq;\nimport static org.mockito.Mockito.mock;\nimport static org.mockito.Mockito.verify;\nimport static org.mockito.Mockito.when;\n\nimport com.mx.josesaid.develop.usuarios_accesos.domain.Usuario;\nimport com.mx.josesaid.develop.usuarios_accesos.domain.UsuarioRepositorio;\nimport io.micrometer.core.instrument.simple.SimpleMeterRegistry;\nimport java.time.Clock;\nimport java.util.List;\nimport org.junit.jupiter.api.Test;\nimport org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder;\n\nclass UsuarioListarRecientesTest {\n\n    @Test\n    void pideHastaQuinceUsuarios() {\n        UsuarioRepositorio repositorio = mock(UsuarioRepositorio.class);\n        Usuario usuario = mock(Usuario.class);\n        when(repositorio.listarRecientes(eq(15))).thenReturn(List.of(usuario));\n        UsuarioService servicio = new UsuarioService(repositorio, new BCryptPasswordEncoder(),\n                mock(PublicadorEventos.class), Clock.systemUTC(), new SimpleMeterRegistry());\n\n        assertThat(servicio.listarRecientes()).containsExactly(usuario);\n        verify(repositorio).listarRecientes(15);\n    }\n}\n", "src/test/java/com/mx/josesaid/develop/usuarios_accesos/application/UsuarioServiceTest.java": "package com.mx.josesaid.develop.usuarios_accesos.application;\n\nimport static org.assertj.core.api.Assertions.assertThat;\nimport static org.assertj.core.api.Assertions.assertThatThrownBy;\n\nimport com.mx.josesaid.develop.usuarios_accesos.domain.ConflictoException;\nimport com.mx.josesaid.develop.usuarios_accesos.domain.CredencialesInvalidasException;\nimport com.mx.josesaid.develop.usuarios_accesos.domain.Rol;\nimport com.mx.josesaid.develop.usuarios_accesos.domain.Usuario;\nimport com.mx.josesaid.develop.usuarios_accesos.domain.UsuarioRepositorio;\nimport java.time.Clock;\nimport java.time.Instant;\nimport java.time.ZoneOffset;\nimport java.util.ArrayList;\nimport java.util.HashMap;\nimport java.util.List;\nimport java.util.Map;\nimport java.util.Optional;\nimport java.util.Set;\nimport java.util.UUID;\nimport org.junit.jupiter.api.BeforeEach;\nimport org.junit.jupiter.api.Test;\nimport org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder;\n\nclass UsuarioServiceTest {\n\n    private final Map<UUID, Usuario> almacen = new HashMap<>();\n    private final List<EventoDominio> eventos = new ArrayList<>();\n    private UsuarioService servicio;\n\n    /** Repositorio en memoria: prueba la lógica de aplicación sin base de datos. */\n    private final UsuarioRepositorio repositorio = new UsuarioRepositorio() {\n        @Override\n        public Usuario guardar(Usuario usuario) {\n            almacen.put(usuario.getId(), usuario);\n            return usuario;\n        }\n\n        @Override\n        public Optional<Usuario> buscarPorId(UUID id) {\n            return Optional.ofNullable(almacen.get(id));\n        }\n\n        @Override\n        public Optional<Usuario> buscarPorCorreo(String correo) {\n            return almacen.values().stream().filter(u -> u.getCorreo().equals(correo)).findFirst();\n        }\n\n        @Override\n        public boolean existePorCorreo(String correo) {\n            return buscarPorCorreo(correo).isPresent();\n        }\n\n        @Override\n        public java.util.List<Usuario> listarRecientes(int limite) {\n            return almacen.values().stream().limit(limite).toList();\n        }\n    };\n\n    @BeforeEach\n    void preparar() {\n        Clock reloj = Clock.fixed(Instant.parse(\"2026-10-29T15:00:00Z\"), ZoneOffset.UTC);\n        servicio = new UsuarioService(repositorio, new BCryptPasswordEncoder(), eventos::add, reloj, new io.micrometer.core.instrument.simple.SimpleMeterRegistry());\n    }\n\n    @Test\n    void autenticaConCredencialesCorrectas() {\n        servicio.crear(\"ana@empresa.mx\", \"Ana Ruiz\", \"clave-segura-1\", Set.of(Rol.VENTAS));\n        Usuario u = servicio.autenticar(\"ANA@empresa.mx\", \"clave-segura-1\");\n        assertThat(u.getCorreo()).isEqualTo(\"ana@empresa.mx\");\n        assertThat(u.getIntentosFallidos()).isZero();\n    }\n\n    @Test\n    void contrasenaIncorrectaGuardaElIntentoYRechaza() {\n        servicio.crear(\"ana@empresa.mx\", \"Ana Ruiz\", \"clave-segura-1\", Set.of(Rol.VENTAS));\n        assertThatThrownBy(() -> servicio.autenticar(\"ana@empresa.mx\", \"otra\"))\n                .isInstanceOf(CredencialesInvalidasException.class);\n        Usuario guardado = almacen.values().iterator().next();\n        assertThat(guardado.getIntentosFallidos()).isEqualTo(1);\n    }\n\n    @Test\n    void quintoIntentoFallidoPublicaEventoDeBloqueo() {\n        servicio.crear(\"ana@empresa.mx\", \"Ana Ruiz\", \"clave-segura-1\", Set.of(Rol.VENTAS));\n        for (int i = 0; i < Usuario.MAX_INTENTOS_FALLIDOS; i++) {\n            assertThatThrownBy(() -> servicio.autenticar(\"ana@empresa.mx\", \"mala\"))\n                    .isInstanceOf(CredencialesInvalidasException.class);\n        }\n        assertThat(eventos).hasSize(1);\n        assertThat(eventos.get(0).tipo()).isEqualTo(UsuarioService.EVENTO_USUARIO_BLOQUEADO);\n    }\n\n    @Test\n    void noPermiteCorreoDuplicado() {\n        servicio.crear(\"ana@empresa.mx\", \"Ana Ruiz\", \"clave-segura-1\", Set.of(Rol.VENTAS));\n        assertThatThrownBy(() -> servicio.crear(\"ANA@empresa.mx\", \"Otra\", \"clave\", Set.of(Rol.VENTAS)))\n                .isInstanceOf(ConflictoException.class);\n    }\n\n    @Test\n    void cambiarRolesPublicaEventoConRolesAnterioresYNuevos() {\n        Usuario u = servicio.crear(\"ana@empresa.mx\", \"Ana Ruiz\", \"clave-segura-1\", Set.of(Rol.VENTAS));\n        servicio.asignarRoles(u.getId(), Set.of(Rol.CONTADOR), \"Cambio de área\");\n        EventoDominio evento = eventos.get(0);\n        assertThat(evento.tipo()).isEqualTo(UsuarioService.EVENTO_ROL_ASIGNADO);\n        assertThat(evento.datos()).containsEntry(\"rolesAnteriores\", List.of(\"VENTAS\"))\n                .containsEntry(\"rolesNuevos\", List.of(\"CONTADOR\"));\n    }\n\n    @Test\n    void credencialesDeUsuarioInexistenteNoRevelanLaExistencia() {\n        assertThatThrownBy(() -> servicio.autenticar(\"nadie@empresa.mx\", \"x\"))\n                .isInstanceOf(CredencialesInvalidasException.class)\n                .hasMessage(\"Correo o contraseña incorrectos\");\n    }\n}\n", "src/test/java/com/mx/josesaid/develop/usuarios_accesos/config/ClavesJwtTest.java": "package com.mx.josesaid.develop.usuarios_accesos.config;\n\nimport static org.assertj.core.api.Assertions.assertThat;\nimport static org.assertj.core.api.Assertions.assertThatThrownBy;\n\nimport java.security.KeyPair;\nimport java.security.KeyPairGenerator;\nimport java.security.interfaces.RSAPublicKey;\nimport java.util.Base64;\nimport org.junit.jupiter.api.Test;\n\nclass ClavesJwtTest {\n\n    private static KeyPair par() throws Exception {\n        KeyPairGenerator generador = KeyPairGenerator.getInstance(\"RSA\");\n        generador.initialize(2048);\n        return generador.generateKeyPair();\n    }\n\n    @Test\n    void elKidConfiguradoSeUsaYElDefectoEsElAnterior() throws Exception {\n        String privada = Base64.getEncoder().encodeToString(par().getPrivate().getEncoded());\n        assertThat(ClavesJwt.desdeBase64(privada, \"nueva-2026\").getKeyID()).isEqualTo(\"nueva-2026\");\n        assertThat(ClavesJwt.desdeBase64(privada, null).getKeyID()).isEqualTo(ClavesJwt.KID_POR_DEFECTO);\n    }\n\n    @Test\n    void laClavePublicaAnteriorConservaSuModuloYSuKid() throws Exception {\n        KeyPair vieja = par();\n        String publicaVieja = Base64.getEncoder().encodeToString(vieja.getPublic().getEncoded());\n        var anterior = ClavesJwt.publicaAnterior(publicaVieja, \"vieja-2025\", \"nueva-2026\");\n        assertThat(anterior.getKeyID()).isEqualTo(\"vieja-2025\");\n        assertThat(anterior.toRSAPublicKey().getModulus()).isEqualTo(((RSAPublicKey) vieja.getPublic()).getModulus());\n        assertThat(anterior.isPrivate()).isFalse();\n    }\n\n    @Test\n    void laClaveAnteriorNoPuedeTenerElMismoKidQueLaActual() throws Exception {\n        String publica = Base64.getEncoder().encodeToString(par().getPublic().getEncoded());\n        assertThatThrownBy(() -> ClavesJwt.publicaAnterior(publica, \"igual\", \"igual\"))\n                .isInstanceOf(IllegalStateException.class);\n    }\n}\n", "src/test/java/com/mx/josesaid/develop/usuarios_accesos/domain/UsuarioTest.java": "package com.mx.josesaid.develop.usuarios_accesos.domain;\n\nimport static org.assertj.core.api.Assertions.assertThat;\nimport static org.assertj.core.api.Assertions.assertThatThrownBy;\n\nimport java.time.Instant;\nimport java.util.List;\nimport org.junit.jupiter.api.Test;\n\nclass UsuarioTest {\n\n    private static final Instant AHORA = Instant.parse(\"2026-10-29T15:00:00Z\");\n\n    private Usuario nuevo() {\n        return Usuario.crear(\"  Ana@Empresa.MX \", \"Ana Ruiz\", \"hash\", List.of(Rol.VENTAS));\n    }\n\n    @Test\n    void normalizaElCorreoAMinusculasSinEspacios() {\n        assertThat(nuevo().getCorreo()).isEqualTo(\"ana@empresa.mx\");\n    }\n\n    @Test\n    void rechazaUsuarioSinRoles() {\n        assertThatThrownBy(() -> Usuario.crear(\"a@b.mx\", \"Ana\", \"hash\", List.of()))\n                .isInstanceOf(ReglaDeNegocioException.class)\n                .hasMessageContaining(\"al menos un rol\");\n    }\n\n    @Test\n    void rechazaCorreoSinArroba() {\n        assertThatThrownBy(() -> Usuario.normalizarCorreo(\"ana.empresa.mx\"))\n                .isInstanceOf(ReglaDeNegocioException.class);\n    }\n\n    @Test\n    void bloqueaEnElQuintoIntentoFallido() {\n        Usuario u = nuevo();\n        for (int i = 1; i < Usuario.MAX_INTENTOS_FALLIDOS; i++) {\n            assertThat(u.registrarIntentoFallido(AHORA)).isFalse();\n        }\n        assertThat(u.registrarIntentoFallido(AHORA)).isTrue();\n        assertThat(u.getEstatus()).isEqualTo(EstatusUsuario.BLOQUEADO);\n    }\n\n    @Test\n    void cuentaBloqueadaNoPuedeIntentarAccesoAntesDelPlazo() {\n        Usuario u = nuevo();\n        for (int i = 0; i < Usuario.MAX_INTENTOS_FALLIDOS; i++) {\n            u.registrarIntentoFallido(AHORA);\n        }\n        assertThatThrownBy(() -> u.verificarAcceso(AHORA.plusSeconds(60)))\n                .isInstanceOf(BloqueoException.class);\n    }\n\n    @Test\n    void desbloqueaCuandoVenceElPlazo() {\n        Usuario u = nuevo();\n        for (int i = 0; i < Usuario.MAX_INTENTOS_FALLIDOS; i++) {\n            u.registrarIntentoFallido(AHORA);\n        }\n        u.verificarAcceso(AHORA.plus(Usuario.DURACION_BLOQUEO).plusSeconds(1));\n        assertThat(u.getEstatus()).isEqualTo(EstatusUsuario.ACTIVO);\n        assertThat(u.getIntentosFallidos()).isZero();\n    }\n\n    @Test\n    void loginExitosoReiniciaLosIntentos() {\n        Usuario u = nuevo();\n        u.registrarIntentoFallido(AHORA);\n        u.registrarIntentoFallido(AHORA);\n        u.registrarLoginExitoso();\n        assertThat(u.getIntentosFallidos()).isZero();\n    }\n\n    @Test\n    void bajaEsDefinitivaYNoPermiteAcceso() {\n        Usuario u = nuevo();\n        u.darDeBaja();\n        assertThatThrownBy(() -> u.verificarAcceso(AHORA))\n                .isInstanceOf(CredencialesInvalidasException.class);\n        assertThatThrownBy(u::darDeBaja).isInstanceOf(ReglaDeNegocioException.class);\n    }\n\n    @Test\n    void asignarRolesRequiereMotivo() {\n        Usuario u = nuevo();\n        assertThatThrownBy(() -> u.asignarRoles(List.of(Rol.ADMIN), \" \"))\n                .isInstanceOf(ReglaDeNegocioException.class)\n                .hasMessageContaining(\"motivo\");\n    }\n\n    @Test\n    void asignarRolesReemplazaLosRoles() {\n        Usuario u = nuevo();\n        u.asignarRoles(List.of(Rol.CONTADOR, Rol.FINANZAS), \"Cambio de área\");\n        assertThat(u.getRoles()).containsExactlyInAnyOrder(Rol.CONTADOR, Rol.FINANZAS);\n    }\n\n    @Test\n    void noPermiteAsignarRolesAUsuarioDadoDeBaja() {\n        Usuario u = nuevo();\n        u.darDeBaja();\n        assertThatThrownBy(() -> u.asignarRoles(List.of(Rol.ADMIN), \"motivo\"))\n                .isInstanceOf(ReglaDeNegocioException.class);\n    }\n\n    @Test\n    void jefeDeAreaRequiereAreaAsignada() {\n        Usuario u = nuevo();\n        assertThatThrownBy(() -> u.asignarRoles(List.of(Rol.JEFE_AREA), \"motivo\"))\n                .isInstanceOf(ReglaDeNegocioException.class)\n                .hasMessageContaining(\"área\");\n    }\n\n    @Test\n    void jefeDeAreaConAreaAsignadaSeAsignaSinError() {\n        Usuario u = nuevo();\n        u.asignarArea(\"VENTAS_ATENCION_CLIENTES\", \"Alta en el área\");\n        u.asignarRoles(List.of(Rol.JEFE_AREA), \"Nuevo jefe\");\n        assertThat(u.getRoles()).containsExactly(Rol.JEFE_AREA);\n        assertThat(u.getArea()).isEqualTo(\"VENTAS_ATENCION_CLIENTES\");\n    }\n\n    @Test\n    void asignarAreaRequiereMotivoYArea() {\n        Usuario u = nuevo();\n        assertThatThrownBy(() -> u.asignarArea(\"VENTAS_ATENCION_CLIENTES\", \" \"))\n                .isInstanceOf(ReglaDeNegocioException.class)\n                .hasMessageContaining(\"motivo\");\n        assertThatThrownBy(() -> u.asignarArea(\" \", \"motivo\"))\n                .isInstanceOf(ReglaDeNegocioException.class)\n                .hasMessageContaining(\"área\");\n    }\n\n    @Test\n    void asignarAreaRechazaUnAreaQueNoExiste() {\n        Usuario u = nuevo();\n        assertThatThrownBy(() -> u.asignarArea(\"VENTAS_ATENCION\", \"motivo\"))\n                .isInstanceOf(ReglaDeNegocioException.class)\n                .hasMessageContaining(\"Área no válida\");\n        assertThat(u.getArea()).isNull();\n    }\n\n    @Test\n    void passwordTemporalSeQuitaAlCambiarla() {\n        Usuario usuario = nuevo();\n        usuario.marcarPasswordTemporal();\n        assertThat(usuario.debeCambiarPassword()).isTrue();\n\n        usuario.cambiarPasswordTemporal(\"nuevo-hash\");\n\n        assertThat(usuario.debeCambiarPassword()).isFalse();\n        assertThat(usuario.getPasswordHash()).isEqualTo(\"nuevo-hash\");\n    }\n\n    @Test\n    void cambiarPasswordSinSerTemporalFalla() {\n        assertThatThrownBy(() -> nuevo().cambiarPasswordTemporal(\"otro-hash\"))\n                .isInstanceOf(ReglaDeNegocioException.class);\n    }\n}\n", "src/test/java/com/mx/josesaid/develop/usuarios_accesos/infrastructure/crypto/CampoCifradoConverterTest.java": "package com.mx.josesaid.develop.usuarios_accesos.infrastructure.crypto;\n\nimport static org.assertj.core.api.Assertions.assertThat;\n\nimport org.junit.jupiter.api.BeforeAll;\nimport org.junit.jupiter.api.Test;\n\nclass CampoCifradoConverterTest {\n\n    @BeforeAll\n    static void claves() {\n        ClavesCripto.configurar(\"0123456789abcdef0123456789abcdef\".getBytes(),\n                \"fedcba9876543210fedcba9876543210\".getBytes());\n    }\n\n    @Test\n    void idaYVueltaRecuperaElTexto() {\n        CampoCifradoConverter c = new CampoCifradoConverter();\n        String cifrado = c.convertToDatabaseColumn(\"contador@empresa.mx\");\n        assertThat(cifrado).isNotEqualTo(\"contador@empresa.mx\");\n        assertThat(c.convertToEntityAttribute(cifrado)).isEqualTo(\"contador@empresa.mx\");\n    }\n\n    @Test\n    void mismoTextoProduceCifradosDistintos() {\n        CampoCifradoConverter c = new CampoCifradoConverter();\n        assertThat(c.convertToDatabaseColumn(\"ana@empresa.mx\"))\n                .isNotEqualTo(c.convertToDatabaseColumn(\"ana@empresa.mx\"));\n    }\n\n    @Test\n    void indiceNoDependeDeMayusculasNiEspacios() {\n        assertThat(IndiceCorreo.de(\"A@empresa.mx\")).isEqualTo(IndiceCorreo.de(\" a@EMPRESA.mx \"));\n    }\n}\n", "src/test/java/com/mx/josesaid/develop/usuarios_accesos/infrastructure/crypto/CampoCifradoVersionTest.java": "package com.mx.josesaid.develop.usuarios_accesos.infrastructure.crypto;\n\nimport static org.assertj.core.api.Assertions.assertThat;\nimport static org.assertj.core.api.Assertions.assertThatThrownBy;\n\nimport java.nio.ByteBuffer;\nimport java.nio.charset.StandardCharsets;\nimport java.security.SecureRandom;\nimport java.util.Base64;\nimport java.util.Map;\nimport javax.crypto.Cipher;\nimport javax.crypto.spec.GCMParameterSpec;\nimport javax.crypto.spec.SecretKeySpec;\nimport org.junit.jupiter.api.BeforeEach;\nimport org.junit.jupiter.api.Test;\n\nclass CampoCifradoVersionTest {\n\n    private final CampoCifradoConverter convertidor = new CampoCifradoConverter();\n    private final SecureRandom aleatorio = new SecureRandom();\n    private byte[] clave1;\n    private byte[] clave2;\n\n    @BeforeEach\n    void configurarClaves() {\n        clave1 = bytesAleatorios();\n        clave2 = bytesAleatorios();\n        ClavesCripto.configurar(Map.of(1, clave1), 1, bytesAleatorios());\n    }\n\n    @Test\n    void escribeConPrefijoDeVersionActiva() {\n        assertThat(convertidor.convertToDatabaseColumn(\"ana@empresa.mx\")).startsWith(\"v1:\");\n    }\n\n    @Test\n    void leeValorAntiguoSinPrefijoComoVersionUno() {\n        String antiguo = cifrarSinPrefijo(\"ana@empresa.mx\", clave1);\n        assertThat(convertidor.convertToEntityAttribute(antiguo)).isEqualTo(\"ana@empresa.mx\");\n    }\n\n    @Test\n    void escribeConVersionNuevaYLeeLaAnterior() {\n        String viejo = convertidor.convertToDatabaseColumn(\"antes de rotar\");\n        ClavesCripto.configurar(Map.of(1, clave1, 2, clave2), 2, bytesAleatorios());\n\n        String nuevo = convertidor.convertToDatabaseColumn(\"despues de rotar\");\n\n        assertThat(nuevo).startsWith(\"v2:\");\n        assertThat(convertidor.convertToEntityAttribute(nuevo)).isEqualTo(\"despues de rotar\");\n        assertThat(convertidor.convertToEntityAttribute(viejo)).isEqualTo(\"antes de rotar\");\n    }\n\n    @Test\n    void versionNoConfiguradaFalla() {\n        String columna = \"v9:\" + Base64.getEncoder().encodeToString(new byte[40]);\n        assertThatThrownBy(() -> convertidor.convertToEntityAttribute(columna))\n                .isInstanceOf(IllegalStateException.class)\n                .hasMessageContaining(\"Versión de clave de cifrado no configurada: 9\");\n    }\n\n    @Test\n    void versionActivaDebeEstarConfigurada() {\n        assertThatThrownBy(() -> ClavesCripto.configurar(Map.of(1, clave1), 2, bytesAleatorios()))\n                .isInstanceOf(IllegalStateException.class);\n    }\n\n    private byte[] bytesAleatorios() {\n        byte[] bytes = new byte[32];\n        aleatorio.nextBytes(bytes);\n        return bytes;\n    }\n\n    /** Replica el formato anterior (sin prefijo) para verificar la compatibilidad. */\n    private String cifrarSinPrefijo(String texto, byte[] clave) {\n        try {\n            byte[] iv = new byte[12];\n            aleatorio.nextBytes(iv);\n            Cipher cipher = Cipher.getInstance(\"AES/GCM/NoPadding\");\n            cipher.init(Cipher.ENCRYPT_MODE, new SecretKeySpec(clave, \"AES\"), new GCMParameterSpec(128, iv));\n            byte[] cifrado = cipher.doFinal(texto.getBytes(StandardCharsets.UTF_8));\n            return Base64.getEncoder().encodeToString(ByteBuffer.allocate(iv.length + cifrado.length).put(iv).put(cifrado).array());\n        } catch (Exception e) {\n            throw new IllegalStateException(e);\n        }\n    }\n}\n", "src/test/java/com/mx/josesaid/develop/usuarios_accesos/infrastructure/crypto/RecifradorPorLotesTest.java": "package com.mx.josesaid.develop.usuarios_accesos.infrastructure.crypto;\n\nimport static org.assertj.core.api.Assertions.assertThat;\nimport static org.assertj.core.api.Assertions.assertThatThrownBy;\n\nimport java.security.SecureRandom;\nimport java.util.ArrayList;\nimport java.util.LinkedHashMap;\nimport java.util.List;\nimport java.util.Map;\nimport java.util.UUID;\nimport org.junit.jupiter.api.BeforeEach;\nimport org.junit.jupiter.api.Test;\n\nclass RecifradorPorLotesTest {\n\n    private final CampoCifradoConverter convertidor = new CampoCifradoConverter();\n    private final SecureRandom aleatorio = new SecureRandom();\n    private byte[] clave1;\n    private byte[] clave2;\n\n    @BeforeEach\n    void claves() {\n        clave1 = bytes();\n        clave2 = bytes();\n        ClavesCripto.configurar(Map.of(1, clave1), 1, bytes());\n    }\n\n    @Test\n    void recifraTodasLasFilasPendientesYNoQuedaNinguna() {\n        String viejo1 = convertidor.convertToDatabaseColumn(\"ana@empresa.mx\");\n        String viejo2 = convertidor.convertToDatabaseColumn(\"luis@empresa.mx\");\n        ClavesCripto.configurar(Map.of(1, clave1, 2, clave2), 2, bytes());\n        AlmacenEnMemoria almacen = new AlmacenEnMemoria();\n        almacen.agregar(UUID.randomUUID(), viejo1);\n        almacen.agregar(UUID.randomUUID(), viejo2);\n\n        int recifradas = recifrador(almacen, 10).ejecutar(\"contacto\", \"correo_cifrado\");\n\n        assertThat(recifradas).isEqualTo(2);\n        assertThat(almacen.valores()).allSatisfy(v -> assertThat(v).startsWith(\"v2:\"));\n        assertThat(almacen.valores()).allSatisfy(v -> assertThat(convertidor.convertToEntityAttribute(v))\n                .isIn(\"ana@empresa.mx\", \"luis@empresa.mx\"));\n    }\n\n    @Test\n    void respetaElTamanoDeLote() {\n        AlmacenEnMemoria almacen = new AlmacenEnMemoria();\n        for (int i = 0; i < 5; i++) {\n            almacen.agregar(UUID.randomUUID(), convertidor.convertToDatabaseColumn(\"dato\" + i));\n        }\n        ClavesCripto.configurar(Map.of(1, clave1, 2, clave2), 2, bytes());\n\n        recifrador(almacen, 2).ejecutar(\"cliente\", \"rfc_cifrado\");\n\n        assertThat(almacen.limitesPedidos).containsOnly(2);\n        assertThat(almacen.valores()).allSatisfy(v -> assertThat(v).startsWith(\"v2:\"));\n    }\n\n    @Test\n    void omiteLasFilasYaEnLaVersionActiva() {\n        ClavesCripto.configurar(Map.of(1, clave1, 2, clave2), 2, bytes());\n        AlmacenEnMemoria almacen = new AlmacenEnMemoria();\n        String yaNueva = convertidor.convertToDatabaseColumn(\"ya nueva\");\n        almacen.agregar(UUID.randomUUID(), yaNueva);\n\n        int recifradas = recifrador(almacen, 10).ejecutar(\"cliente\", \"rfc_cifrado\");\n\n        assertThat(recifradas).isZero();\n        assertThat(almacen.valores()).containsExactly(yaNueva);\n    }\n\n    @Test\n    void reanudarDespuesDeUnCorteNoDuplicaNiPierde() {\n        String viejo1 = convertidor.convertToDatabaseColumn(\"uno\");\n        String viejo2 = convertidor.convertToDatabaseColumn(\"dos\");\n        ClavesCripto.configurar(Map.of(1, clave1, 2, clave2), 2, bytes());\n        AlmacenEnMemoria almacen = new AlmacenEnMemoria();\n        almacen.agregar(UUID.randomUUID(), viejo1);\n        almacen.agregar(UUID.randomUUID(), viejo2);\n        almacen.fallarEnActualizacion = 2;\n\n        assertThatThrownBy(() -> recifrador(almacen, 1).ejecutar(\"interaccion\", \"resumen_cifrado\"))\n                .isInstanceOf(IllegalStateException.class);\n        almacen.fallarEnActualizacion = 0;\n        int segundaCorrida = recifrador(almacen, 1).ejecutar(\"interaccion\", \"resumen_cifrado\");\n\n        assertThat(segundaCorrida).isEqualTo(1);\n        assertThat(almacen.valores()).allSatisfy(v -> assertThat(v).startsWith(\"v2:\"));\n    }\n\n    @Test\n    void siUnaFilaCambiaDuranteElProcesoSeAvisa() {\n        AlmacenEnMemoria almacen = new AlmacenEnMemoria();\n        almacen.agregar(UUID.randomUUID(), convertidor.convertToDatabaseColumn(\"x\"));\n        ClavesCripto.configurar(Map.of(1, clave1, 2, clave2), 2, bytes());\n        almacen.rechazarActualizacion = true;\n\n        assertThatThrownBy(() -> recifrador(almacen, 10).ejecutar(\"contacto\", \"nombre_cifrado\"))\n                .isInstanceOf(IllegalStateException.class)\n                .hasMessageContaining(\"cambió durante el proceso\");\n    }\n\n    @Test\n    void tamanoDeLoteDebeSerPositivo() {\n        assertThatThrownBy(() -> new RecifradorPorLotes(new AlmacenEnMemoria(), 0, v -> v))\n                .isInstanceOf(IllegalArgumentException.class);\n    }\n\n    @Test\n    void versionDeIdentificaPrefijoOSinPrefijo() {\n        assertThat(CampoCifradoConverter.versionDe(\"v7:AAAA\")).isEqualTo(7);\n        assertThat(CampoCifradoConverter.versionDe(\"AAAA\")).isEqualTo(1);\n    }\n\n    private RecifradorPorLotes recifrador(RecifradorPorLotes.Almacen almacen, int lote) {\n        return new RecifradorPorLotes(almacen, lote,\n                valor -> convertidor.convertToDatabaseColumn(convertidor.convertToEntityAttribute(valor)));\n    }\n\n    private byte[] bytes() {\n        byte[] b = new byte[32];\n        aleatorio.nextBytes(b);\n        return b;\n    }\n\n    /** Almacén en memoria con las mismas reglas que la consulta JDBC. */\n    private static final class AlmacenEnMemoria implements RecifradorPorLotes.Almacen {\n        private final Map<Object, String> filas = new LinkedHashMap<>();\n        private final List<Integer> limitesPedidos = new ArrayList<>();\n        private int fallarEnActualizacion;\n        private boolean rechazarActualizacion;\n        private int actualizaciones;\n\n        void agregar(Object id, String valor) {\n            filas.put(id, valor);\n        }\n\n        List<String> valores() {\n            return new ArrayList<>(filas.values());\n        }\n\n        @Override\n        public List<RecifradorPorLotes.Fila> pendientes(String tabla, String columna, int limite) {\n            limitesPedidos.add(limite);\n            String prefijo = \"v\" + ClavesCripto.versionActiva() + \":\";\n            List<RecifradorPorLotes.Fila> salida = new ArrayList<>();\n            for (Map.Entry<Object, String> e : filas.entrySet()) {\n                if (!e.getValue().startsWith(prefijo) && salida.size() < limite) {\n                    salida.add(new RecifradorPorLotes.Fila(e.getKey(), e.getValue()));\n                }\n            }\n            return salida;\n        }\n\n        @Override\n        public boolean actualizar(String tabla, String columna, Object id, String valorAnterior, String valorNuevo) {\n            if (fallarEnActualizacion > 0 && ++actualizaciones == fallarEnActualizacion) {\n                throw new IllegalStateException(\"corte simulado\");\n            }\n            if (rechazarActualizacion || !valorAnterior.equals(filas.get(id))) {\n                return false;\n            }\n            filas.put(id, valorNuevo);\n            return true;\n        }\n    }\n}\n", "src/test/java/com/mx/josesaid/develop/usuarios_accesos/infrastructure/indicadores/PublicadorIndicadoresUsuariosIT.java": "package com.mx.josesaid.develop.usuarios_accesos.infrastructure.indicadores;\n\nimport static org.junit.jupiter.api.Assertions.assertEquals;\n\nimport com.jayway.jsonpath.JsonPath;\nimport java.time.Duration;\nimport java.time.YearMonth;\nimport java.time.ZoneId;\nimport java.util.Collections;\nimport java.util.Properties;\nimport java.util.UUID;\nimport org.apache.kafka.clients.consumer.ConsumerConfig;\nimport org.apache.kafka.clients.consumer.KafkaConsumer;\nimport org.apache.kafka.common.serialization.StringDeserializer;\nimport org.junit.jupiter.api.Test;\nimport org.springframework.beans.factory.annotation.Autowired;\nimport org.springframework.boot.test.context.SpringBootTest;\nimport org.springframework.boot.testcontainers.service.connection.ServiceConnection;\nimport org.springframework.jdbc.core.JdbcTemplate;\nimport org.testcontainers.junit.jupiter.Container;\nimport org.testcontainers.junit.jupiter.Testcontainers;\nimport org.testcontainers.kafka.KafkaContainer;\nimport org.testcontainers.postgresql.PostgreSQLContainer;\n\n/** Integración con PostgreSQL y Kafka reales (Testcontainers). Requiere Docker; corre con 'mvn verify'. */\n@SpringBootTest\n@Testcontainers\nclass PublicadorIndicadoresUsuariosIT {\n\n    /** Claves de prueba: la clave RSA se genera en cada ejecución; las de cifrado son fijas solo para pruebas. */\n    @org.springframework.test.context.DynamicPropertySource\n    static void clavesDePrueba(org.springframework.test.context.DynamicPropertyRegistry registro) throws Exception {\n        java.security.KeyPairGenerator generador = java.security.KeyPairGenerator.getInstance(\"RSA\");\n        generador.initialize(2048);\n        String pkcs8 = java.util.Base64.getEncoder().encodeToString(generador.generateKeyPair().getPrivate().getEncoded());\n        registro.add(\"usuarios.jwt.clave-privada\", () -> pkcs8);\n        registro.add(\"USUARIOS_CIFRADO_CLAVE\", () -> java.util.Base64.getEncoder()\n                .encodeToString(\"0123456789abcdef0123456789abcdef\".getBytes()));\n        registro.add(\"USUARIOS_INDICE_CLAVE\", () -> java.util.Base64.getEncoder()\n                .encodeToString(\"fedcba9876543210fedcba9876543210\".getBytes()));\n    }\n\n    @Container\n    @ServiceConnection\n    static PostgreSQLContainer postgres = new PostgreSQLContainer(\"postgres:17-alpine\");\n\n    @Container\n    @ServiceConnection\n    static KafkaContainer kafka = new KafkaContainer(\"apache/kafka:4.0.0\");\n\n    @Autowired\n    private JdbcTemplate jdbc;\n\n    @Autowired\n    private PublicadorIndicadoresUsuarios publicador;\n\n    private static final ZoneId ZONA = ZoneId.of(\"America/Mexico_City\");\n\n    @Test\n    void usuariosActivosCuentaSoloElEstatusActivo() {\n        String periodo = YearMonth.now(ZONA).toString();\n        // El arranque puede crear un administrador inicial ACTIVO; se cuenta la base existente.\n        long base = jdbc.queryForObject(\"SELECT COUNT(*) FROM usuarios WHERE estatus = 'ACTIVO'\", Long.class);\n        usuario(\"ACTIVO\");\n        usuario(\"ACTIVO\");\n        usuario(\"BLOQUEADO\");  // excluido\n        usuario(\"BAJA\");       // excluido\n\n        publicador.publicar();\n\n        String clave = PublicadorIndicadoresUsuarios.AREA + \"|\" + PublicadorIndicadoresUsuarios.NOMBRE + \"|\" + periodo;\n        String payload = leerIndicador(clave);\n        assertEquals(\"ADMINISTRACION_LEGAL\", JsonPath.read(payload, \"$.area\"));\n        assertEquals(base + 2.0, ((Number) JsonPath.read(payload, \"$.valor\")).doubleValue(), 0.001);\n    }\n\n    private void usuario(String estatus) {\n        jdbc.update(\"\"\"\n                INSERT INTO usuarios (id, correo, nombre_completo, password_hash, estatus, creado_utc, actualizado_utc)\n                VALUES (?, ?, 'Usuario de prueba', 'hash', ?, now(), now())\n                \"\"\", UUID.randomUUID(), UUID.randomUUID() + \"@prueba.mx\", estatus);\n    }\n\n    private String leerIndicador(String clave) {\n        try (KafkaConsumer<String, String> consumidor = new KafkaConsumer<>(propiedades())) {\n            consumidor.subscribe(Collections.singletonList(\"indicadores-areas\"));\n            long limite = System.currentTimeMillis() + 30_000;\n            while (System.currentTimeMillis() < limite) {\n                for (var registro : consumidor.poll(Duration.ofMillis(500))) {\n                    if (clave.equals(registro.key())) {\n                        return registro.value();\n                    }\n                }\n            }\n            throw new AssertionError(\"No llegó el indicador \" + clave);\n        }\n    }\n\n    private Properties propiedades() {\n        Properties p = new Properties();\n        p.put(ConsumerConfig.BOOTSTRAP_SERVERS_CONFIG, kafka.getBootstrapServers());\n        p.put(ConsumerConfig.GROUP_ID_CONFIG, \"test-\" + UUID.randomUUID());\n        p.put(ConsumerConfig.AUTO_OFFSET_RESET_CONFIG, \"earliest\");\n        p.put(ConsumerConfig.KEY_DESERIALIZER_CLASS_CONFIG, StringDeserializer.class);\n        p.put(ConsumerConfig.VALUE_DESERIALIZER_CLASS_CONFIG, StringDeserializer.class);\n        return p;\n    }\n}\n", "src/test/java/com/mx/josesaid/develop/usuarios_accesos/seguridad/RevocacionSesionesTest.java": "package com.mx.josesaid.develop.usuarios_accesos.seguridad;\n\nimport static org.assertj.core.api.Assertions.assertThat;\n\nimport java.time.Duration;\nimport java.time.Instant;\nimport org.junit.jupiter.api.Test;\n\nclass RevocacionSesionesTest {\n\n    private static final Instant AHORA = Instant.now();\n\n    @Test\n    void unaSesionCerradaRechazaSuSidYNoLasDemas() {\n        RevocacionSesiones revocaciones = new RevocacionSesiones();\n        revocaciones.revocarSesion(\"sesion-1\", AHORA);\n        assertThat(revocaciones.revocado(\"sesion-1\", \"u1\", AHORA.minusSeconds(60))).isTrue();\n        assertThat(revocaciones.revocado(\"sesion-2\", \"u1\", AHORA.minusSeconds(60))).isFalse();\n    }\n\n    @Test\n    void cerrarTodasRechazaSoloLosTokensAnterioresAlCierre() {\n        RevocacionSesiones revocaciones = new RevocacionSesiones();\n        revocaciones.revocarUsuario(\"u1\", AHORA);\n        assertThat(revocaciones.revocado(null, \"u1\", AHORA.minusSeconds(60))).isTrue();\n        assertThat(revocaciones.revocado(null, \"u1\", AHORA.plusSeconds(60))).isFalse();\n        assertThat(revocaciones.revocado(null, \"u2\", AHORA.minusSeconds(60))).isFalse();\n    }\n\n    @Test\n    void unaRevocacionVencidaSeIgnora() {\n        RevocacionSesiones revocaciones = new RevocacionSesiones();\n        revocaciones.revocarSesion(\"sesion-1\", AHORA.minus(Duration.ofHours(1)));\n        assertThat(revocaciones.revocado(\"sesion-1\", \"u1\", AHORA.minus(Duration.ofHours(2)))).isFalse();\n    }\n}\n"};
